/* MODULE gt06 · Bước 3 Đặt giả thuyết · Mục tiêu marketing gắn với mục tiêu kinh doanh
   10 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'gt06', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:gt06-01', skill:'measure', read:'7 phút', t:'Sếp giao 600 triệu doanh thu quý — cần bao nhiêu khách?',
  situation:'Bạn phụ trách marketing cho một tiệm bánh kem online ở Đà Nẵng. Chủ tiệm chốt mục tiêu quý tới: doanh thu 600 triệu đồng. Giá trị đơn trung bình là 400.000 đồng, mỗi khách mua trung bình 1,5 đơn trong quý. Chủ tiệm hỏi: "Vậy marketing phải làm gì?" Bạn chưa có câu trả lời bằng con số.',
  concept:{ name:'Suy ngược từ doanh thu ra số khách',
    body:'Mục tiêu doanh thu là của kinh doanh; marketing cần dịch nó ra con số mình tác động được. Công thức gốc: <b>doanh thu = số khách × số đơn mỗi khách × giá trị đơn</b>. Chia ngược sẽ ra số khách cần có. Con số 1,5 đơn là trung bình: khách mới thường mua một đơn, khách cũ mua nhiều hơn, nên tách hai nhóm mới thấy đòn bẩy “khách cũ quay lại”. Đi tiếp xuống phễu: số khách ÷ tỉ lệ chuyển đổi = số người cần tiếp cận hoặc ghé trang. Mỗi tầng là một đòn bẩy riêng — tăng khách mới, tăng tần suất mua, hay tăng giá trị đơn — và mỗi đòn bẩy cần một kế hoạch khác nhau.' },
  example:'600 triệu ÷ 400.000 đồng = 1.500 đơn. 1.500 đơn ÷ 1,5 đơn mỗi khách = 1.000 khách trong quý. Nếu tỉ lệ chuyển đổi từ người nhắn tin sang người mua là 20%, bạn cần khoảng 5.000 lượt nhắn tin. Giờ câu hỏi "marketing làm gì" đã thành: làm sao có 5.000 cuộc trò chuyện, hoặc nâng chuyển đổi để cần ít hơn.',
  takeaway:'Doanh thu là đích của kinh doanh; số khách và số lượt tiếp cận suy ngược ra mới là việc của marketing.',
  apply:'Lấy mục tiêu doanh thu tháng của một cửa hàng bạn biết, ước giá trị đơn và số đơn mỗi khách, rồi nói trong 60 giây cần bao nhiêu khách.',
  mistakes:['Nhận mục tiêu doanh thu rồi lập kế hoạch nội dung mà không tính ra số khách cần có.','Quên số đơn mỗi khách, tính như thể mỗi khách chỉ mua một lần.'],
  q:[
  { type:'mcq', stem:'Trước khi tính: với mục tiêu 600 triệu, bạn đoán con số nào marketing nên nhận làm mục tiêu trực tiếp?',
    options:[{k:'a',t:'Số khách mua và số lượt nhắn tin cần có, suy ra từ doanh thu'},{k:'b',t:'Chính con số 600 triệu, vì marketing phải chịu trách nhiệm doanh thu cuối cùng'},
             {k:'c',t:'Số bài đăng mỗi tuần, vì marketing tự kiểm soát được việc đó'},{k:'d',t:'Số người theo dõi fanpage, vì trang càng đông thì doanh thu càng tự tăng'}],
    answer:'a', why:{a:'Đúng. Số khách và lượt tiếp cận là con số marketing tác động trực tiếp và nối thẳng về doanh thu.',
      b:'Doanh thu còn phụ thuộc giá, sản phẩm, giao hàng; marketing cần một con số mình điều khiển được.',
      c:'Số bài đăng là đầu vào công việc, không cho biết có đủ khách hay không.',
      d:'Người theo dõi không mua thì không thành doanh thu; nối từ follower đến đơn rất lỏng.'} },
  { type:'mcq', stem:'Tính ra cần 1.000 khách nhưng quý trước tiệm chỉ có 600 khách. Bạn đề xuất gì với chủ tiệm?',
    options:[{k:'a',t:'Nhận 1.000 khách và dồn hết ngân sách vào quảng cáo tìm khách mới'},{k:'b',t:'Tách khoảng hụt ra ba đòn bẩy: thêm khách, tăng tần suất, tăng giá trị đơn'},
             {k:'c',t:'Xin hạ mục tiêu doanh thu xuống 360 triệu cho khớp với số khách hiện có'},{k:'d',t:'Giảm giá 20% các loại bánh để kéo lượng khách mới lên thật nhanh trong quý'}],
    answer:'b', why:{a:'Chỉ kéo khách mới là đòn bẩy đắt nhất; bỏ qua hai đòn bẩy còn lại thường rẻ hơn.',
      b:'Đúng. Tăng tần suất từ 1,5 lên 1,8 hoặc giá trị đơn lên 450.000 đồng có thể lấp một phần hụt mà không cần 400 khách mới.',
      c:'Có thể phải thương lượng, nhưng trước hết phải xem các đòn bẩy làm được gì rồi mới bàn hạ mục tiêu.',
      d:'Giảm giá làm giá trị đơn giảm, nên phải bán nhiều đơn hơn để đạt 600 triệu, mà biên lãi mỗi đơn cũng mỏng đi.'} },
  { type:'calc', stem:'Một tiệm hoa khác đặt mục tiêu quý 540 triệu đồng, giá trị đơn trung bình 450.000 đồng, mỗi khách mua 1,5 đơn trong quý. Cần bao nhiêu khách?',
    unit:'khách', ans:800, tol:1, wrong:[[1200,'NGUOC_TAN_SUAT'],[1800,'NGUOC_TAN_SUAT']], errors:['NGUOC_TAN_SUAT'],
    steps:['Số đơn = 540.000.000 ÷ 450.000 = 1.200 đơn.','Số khách = 1.200 ÷ 1,5 = <b>800 khách</b>.'] },
  { type:'calc', stem:'Tiệm hoa đó cần 800 khách, 25% người nhắn tin sẽ mua, mỗi cuộc nhắn tin tốn 15.000 đồng quảng cáo (số minh hoạ). Chi phí quảng cáo là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:48, tol:0.5, wrong:[[12,'QUEN_TI_LE_CHUYEN_DOI'],[3,'NHAM_DIEM_PHAN_TRAM']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Lượt nhắn tin = 800 ÷ 0,25 = 3.200 lượt.','Chi phí = 3.200 × 15.000 = 48.000.000 = <b>48 triệu đồng</b>.'] },
  { type:'mcq', stem:'Một quán cà phê muốn tăng doanh thu 20% mà không tăng ngân sách quảng cáo. Đòn bẩy nào nên xét trước?',
    options:[{k:'a',t:'Mở thêm kênh TikTok để tìm tệp khách mới chưa biết'},{k:'b',t:'Đổi logo và bảng hiệu cho mới mẻ, thu hút người qua đường'},
             {k:'c',t:'Tăng tần suất quay lại và giá trị ly của khách đang có'},{k:'d',t:'Tăng giá các món 20% để đạt đúng mục tiêu doanh thu'}],
    answer:'c', why:{a:'Kênh mới cần thời gian, công sức và thường cả tiền để có khách.',
      b:'Đổi nhận diện tốn kém và không chắc tăng doanh thu trong ngắn hạn.',
      c:'Đúng. Khách cũ đã biết quán; mời họ quay lại hoặc thêm bánh vào ly là đòn bẩy rẻ nhất.',
      d:'Tăng giá mạnh có thể làm mất khách, doanh thu không tăng đúng 20% như phép nhân.'} },
  { type:'mcq', stem:'Bạn tính ra cần 5.000 lượt nhắn tin nhưng chỉ có ngân sách đủ cho khoảng 3.000 lượt. Bước hợp lý tiếp theo là gì?',
    options:[{k:'a',t:'Cứ chạy 3.000 lượt, cuối quý thiếu thì giải thích là do ngân sách thấp'},{k:'b',t:'Tìm cách nâng chuyển đổi từ nhắn tin lên mua, ví dụ từ 20% lên khoảng 33%'},
             {k:'c',t:'Đăng bài nhiều gấp đôi để bù phần thiếu mà không cần tốn thêm tiền'},{k:'d',t:'Đổi sang đo lượt thích thay cho lượt nhắn tin vì dễ đạt hơn nhiều'}],
    answer:'b', why:{a:'Biết trước sẽ hụt mà không báo và không tìm cách bù là làm mục tiêu chỉ còn trên giấy.',
      b:'Đúng. 1.000 ÷ 3.000 ≈ 33%: nếu kịch bản tư vấn tốt hơn, 3.000 lượt vẫn đủ khách.',
      c:'Số bài đăng không tự thành lượt nhắn tin; cần chứng minh đăng nhiều thì có thêm hội thoại.',
      d:'Đổi thước đo để dễ đạt làm mục tiêu mất liên kết với doanh thu.'} },
  { type:'mcq', stem:'Tiệm bánh ở Đà Nẵng cần 5.000 lượt nhắn tin, mỗi lượt tốn 15.000 đồng quảng cáo (75 triệu). Giả sử biên lãi gộp 30% trên 600 triệu doanh thu, tức 180 triệu. Kết luận nào đúng?',
    options:[{k:'a',t:'Quảng cáo 75 triệu trên 600 triệu doanh thu chỉ 12,5%, nên chắc chắn có lời'},{k:'b',t:'Kế hoạch lỗ, vì 75 triệu quảng cáo cộng giá vốn đã vượt 180 triệu lãi gộp'},
             {k:'c',t:'Không đánh giá được nếu chưa biết số người theo dõi fanpage của tiệm'},{k:'d',t:'Quảng cáo ăn 75 trong 180 triệu lãi gộp, còn 105 triệu để gánh lương, mặt bằng'}],
    answer:'d', why:{a:'So với doanh thu thì dễ đẹp; tiền thật dùng để trả chi phí là lãi gộp, nên phải so với 180 triệu.',
      b:'Giá vốn đã được trừ rồi mới ra lãi gộp; cộng lại là đếm trùng.',
      c:'Số người theo dõi không đi vào phép tính chi phí và lãi gộp của kế hoạch.',
      d:'Đúng. So chi phí quảng cáo với lãi gộp mới biết còn lại bao nhiêu để trả các chi phí khác; đây chưa phải lãi ròng.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:gt06-02', skill:'measure', read:'6 phút', t:'"Tăng 30% follower trong 3 tháng" — SMART rồi, sao vẫn vô nghĩa?',
  situation:'Một thương hiệu mỹ phẩm thuần chay nhỏ ở TP.HCM viết mục tiêu quý: "Tăng follower Instagram từ 10.000 lên 13.000 trong 3 tháng." Cụ thể, đo được, có hạn. Nhưng doanh thu hai quý gần nhất đứng yên dù follower đã tăng đều. Chủ thương hiệu hỏi: mục tiêu này đúng chuẩn SMART, vậy sao không giúp bán hàng?',
  concept:{ name:'SMART nhưng có ý nghĩa',
    body:'SMART (cụ thể, đo được, khả thi, liên quan, có thời hạn) là khung kiểm tra cách viết, không kiểm tra con số có đáng theo đuổi. Chữ <b>R — liên quan</b> hay bị bỏ qua nhất: mục tiêu phải nối được về mục tiêu kinh doanh bằng một chuỗi lý lẽ. Cách thử nhanh: hỏi "đạt được thì sao?" ba lần. Nếu câu trả lời không dẫn tới khách, đơn hay lãi thì mục tiêu đó chỉ đẹp trên giấy.' },
  example:'Hỏi "đạt 13.000 follower thì sao?" — "thì nhiều người thấy bài hơn". "Thì sao?" — "thì… có thể có người mua". Chuỗi đứt ở đó. Viết lại: "Tăng số khách mua lần đầu từ Instagram từ 80 lên 120 mỗi tháng trong quý 3, đo bằng mã giảm giá riêng kênh." Vẫn SMART, nhưng giờ nối thẳng vào doanh thu: thêm 40 khách mỗi tháng, đơn 350.000 đồng, là thêm 14 triệu đồng mỗi tháng.',
  takeaway:'SMART kiểm cách viết; hỏi "đạt được thì sao?" ba lần mới kiểm được ý nghĩa.',
  points:["Mục tiêu chỉ có ý nghĩa khi là một mắt xích trong chuỗi dẫn tới tiền. Follower là mắt xích đầu, giữa nó và doanh thu còn nhiều bước để người ta rơi ra.","Câu hỏi “đạt được thì sao” buộc người viết nói ra giả định ngầm. Đến lần thứ ba, giả định như “có thể có người mua” lộ ra là điều chưa ai kiểm chứng.","Chỉ số nối thẳng vào khách mua lần đầu đo được bằng công cụ sẵn có như mã giảm giá riêng kênh, không tốn thêm hệ thống mới mà vẫn thấy phần đóng góp."],
  counter:"Hỏi ba lần có thể làm bạn bỏ quên giá trị dài hạn. Giả sử thương hiệu này còn ít người biết, và follower là cách chính để khách tìm thấy trang. Khi đó mục tiêu follower có thể hợp lý nếu kèm một bước nối sang mua hàng. Dấu hiệu là chuỗi lý lẽ đứt nhưng bạn giải thích được vì sao cần mắt xích đó. Lúc ấy nên giữ mục tiêu và thêm chỉ số đi sau nó.",
  deeper:"Người làm nghề không bỏ follower, chỉ đặt nó đúng chỗ: là chỉ số dẫn đầu cho sự chú ý, không phải đích. Đánh đổi là mục tiêu nối thẳng về doanh thu thường dao động mạnh hơn và khó đạt hơn, nên phải chấp nhận báo cáo ít đẹp hơn. Tín hiệu nên theo dõi là tỉ lệ người mua trên số người vào từ Instagram, vì nó cho biết follower có biến thành khách hay không. Khái niệm kề cận là phễu từ chú ý đến đơn hàng. Phép kiểm tra trong tuần: lấy số khách mua lần đầu theo mã giảm giá riêng của tháng gần nhất, đặt cạnh mức tăng follower cùng kỳ.",
  apply:'Chọn một mục tiêu marketing bạn từng thấy, hỏi "đạt được thì sao?" ba lần, rồi nói nó dẫn tới doanh thu hay đứt giữa chừng.',
  mistakes:['Coi mục tiêu đúng khuôn SMART là mục tiêu tốt.','Chọn chỉ số dễ đo thay vì chỉ số nối về doanh thu.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: mục tiêu "tăng follower từ 10.000 lên 13.000 trong 3 tháng" yếu nhất ở chữ nào của SMART?',
    options:[{k:'a',t:'S — chưa đủ cụ thể vì không nói rõ nền tảng nào'},{k:'b',t:'T — ba tháng là quá ngắn để tăng 30% follower'},
             {k:'c',t:'R — liên quan: chưa nối được về mục tiêu kinh doanh'},{k:'d',t:'M — follower không đo được chính xác trên Instagram'}],
    answer:'c', why:{a:'Mục tiêu đã nêu Instagram và con số cụ thể.',
      b:'Thời hạn có thể bàn, nhưng chưa phải chỗ yếu chính khi doanh thu đứng yên.',
      c:'Đúng. Mọi chữ khác đều ổn; điều thiếu là lý do con số này giúp bán hàng.',
      d:'Follower đo rất dễ, chính vì dễ đo nên hay được chọn nhầm.'} },
  { type:'mcq', stem:'Chủ thương hiệu nhờ bạn viết lại mục tiêu quý cho Instagram. Bạn chọn cách viết nào?',
    options:[{k:'a',t:'Tăng tương tác trung bình mỗi bài từ 2% lên 4% trong quý 3'},{k:'b',t:'Tăng khách mua lần đầu từ Instagram từ 80 lên 120 mỗi tháng, đo bằng mã riêng'},
             {k:'c',t:'Trở thành thương hiệu thuần chay được yêu thích nhất trên Instagram năm nay'},{k:'d',t:'Đăng đều 5 bài và 3 video ngắn mỗi tuần trong suốt quý 3 tới đây'}],
    answer:'b', why:{a:'Tương tác gần doanh thu hơn follower một chút nhưng vẫn chưa chứng minh được là có người mua.',
      b:'Đúng. Nối thẳng vào khách mua và có cách đo riêng kênh.',
      c:'Không đo được, không có con số; đây là khẩu hiệu chứ không phải mục tiêu.',
      d:'Đây là kế hoạch công việc; hoàn thành đủ bài vẫn có thể không bán thêm được gì.'} },
  { type:'calc', stem:'Thêm 40 khách mua lần đầu mỗi tháng, giá trị đơn 350.000 đồng. Doanh thu tăng thêm trong một quý (3 tháng) là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:42, tol:0.1, wrong:[[14,'SAI_TINH_TOAN'],[168,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Mỗi tháng: 40 × 350.000 = 14 triệu đồng.','Một quý: 14 × 3 = <b>42 triệu đồng</b>.'] },
  { type:'mcq', stem:'Phép thử "đạt được thì sao?" hỏi ba lần giúp phát hiện điều gì?',
    options:[{k:'a',t:'Mục tiêu có đủ khó để team phải cố gắng hết sức hay không'},{k:'b',t:'Chuỗi lý lẽ từ chỉ số marketing đến doanh thu có bị đứt không'},
             {k:'c',t:'Con số nên được viết dạng phần trăm hay dạng số lượng cụ thể'},{k:'d',t:'Ai trong team sẽ chịu trách nhiệm chính cho mục tiêu đó'}],
    answer:'b', why:{a:'Độ khó là chữ A (khả thi), phép thử này không đo độ khó.',
      b:'Đúng. Nếu tới lần hỏi thứ ba vẫn chưa gặp khách hay đơn, chuỗi đã đứt.',
      c:'Định dạng con số là chuyện cách viết, không phải ý nghĩa.',
      d:'Phân công quan trọng nhưng là câu hỏi khác.'} },
  { type:'mcq', stem:'Một nhà sách online đặt mục tiêu "giảm tỉ lệ bỏ giỏ hàng từ 70% xuống 60% trong quý". Nhận xét nào hợp lý nhất?',
    options:[{k:'a',t:'Có ý nghĩa: người bỏ giỏ đã muốn mua, giữ họ lại là thêm đơn trực tiếp'},{k:'b',t:'Vô nghĩa, vì bỏ giỏ là hành vi tự nhiên, marketing không tác động được gì'},
             {k:'c',t:'Chưa SMART vì thiếu tên người phụ trách, nên phải viết lại từ đầu'},{k:'d',t:'Nên đổi sang tăng lượt truy cập vì truy cập là gốc của đơn hàng'}],
    answer:'a', why:{a:'Đúng. Mỗi điểm phần trăm bỏ giỏ giảm được là đơn hàng từ người đã có ý định mua.',
      b:'Nhắc giỏ hàng, phí ship rõ ràng, thanh toán gọn đều tác động được tỉ lệ này.',
      c:'SMART không yêu cầu tên người phụ trách; mục tiêu này đã đủ các chữ.',
      d:'Thêm truy cập mà 70% vẫn bỏ giỏ thì tốn tiền kéo người vào rồi để rơi.'} },
  { type:'mcq', stem:'Vì sao follower hay được chọn làm mục tiêu dù không nối chắc về doanh thu?',
    options:[{k:'a',t:'Vì follower là thứ báo trước doanh thu sát nhất'},{k:'b',t:'Vì nền tảng buộc báo follower mỗi chiến dịch'},
             {k:'c',t:'Vì doanh thu khó tách riêng cho từng kênh MXH'},{k:'d',t:'Vì nó dễ đo, tăng đều và nhìn đẹp trong báo cáo'}],
    answer:'d', why:{a:'Follower có thể tăng mà doanh thu đứng yên, như chính tình huống của bài.',
      b:'Không có quy định như vậy; đó là thói quen báo cáo.',
      c:'Mã giảm giá riêng, link theo dõi, câu hỏi "biết shop qua đâu" đều giúp gán doanh thu cho kênh.',
      d:'Đúng. Dễ đo và dễ tăng là cái bẫy: mục tiêu được chọn vì tiện, không vì ý nghĩa.'} },
  { type:'mcq', stem:'Mục tiêu nào dưới đây vừa SMART vừa nối được về kinh doanh cho một phòng gym khu dân cư?',
    options:[{k:'a',t:'Tăng nhận biết thương hiệu phòng gym trong khu vực lên mức cao'},{k:'b',t:'Đạt 50.000 lượt xem video tập luyện trên TikTok trong tháng 10'},
             {k:'c',t:'Có 60 người tập thử miễn phí đăng ký gói tháng trong tháng 10'},{k:'d',t:'Đăng 30 video hướng dẫn tập mỗi tháng trong suốt cả năm nay'}],
    answer:'c', why:{a:'Không có con số, không có hạn, không đo được.',
      b:'Lượt xem SMART về hình thức nhưng chưa chứng minh được là có hội viên.',
      c:'Đúng. Có số, có hạn, và mỗi người đăng ký gói tháng là doanh thu trực tiếp.',
      d:'Đây là khối lượng công việc, không phải kết quả.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:gt06-03', skill:'brand', read:'7 phút', t:'Mục tiêu thương hiệu hay mục tiêu bán hàng — quý này chọn cái nào?',
  situation:'Một hãng nước mắm đóng chai ở Phú Quốc có ngân sách quý 300 triệu đồng. Giám đốc bán hàng muốn dồn hết vào khuyến mãi "mua 2 tặng 1" trên sàn để đẩy số. Giám đốc thương hiệu muốn một nửa cho video kể chuyện làng nghề để người mua nhớ tên. Cả hai nhờ bạn chia ngân sách và đặt mục tiêu.',
  concept:{ name:'Mục tiêu thương hiệu và mục tiêu bán hàng',
    body:'<b>Mục tiêu bán hàng</b> đo kết quả gần: đơn, doanh thu, khách mới trong kỳ. <b>Mục tiêu thương hiệu</b> đo thứ tích luỹ: bao nhiêu người trong nhóm khách mục tiêu nhớ ra tên bạn khi cần mua, liên tưởng gì tới bạn. Bán hàng cho kết quả nhanh nhưng dừng tiền là dừng đơn; thương hiệu chậm nhưng làm cho mọi đồng khuyến mãi sau này hiệu quả hơn. Không cần chọn một bỏ một: chia ngân sách theo tỉ lệ, và mỗi phần có mục tiêu riêng, đo riêng.' },
  example:'Bạn đề xuất chia 60/40: 180 triệu cho khuyến mãi trên sàn với mục tiêu 3.000 đơn trong quý; 120 triệu cho video làng nghề với mục tiêu tăng tỉ lệ người nhớ ra tên hãng khi được hỏi "kể tên nước mắm Phú Quốc" từ 12% lên 18% trong nhóm khảo sát 300 người. Hai phần có hai thước đo, không phần nào bị đánh giá bằng thước của phần kia. Lưu ý: với 300 người mỗi lần đo, chênh dưới khoảng 6 điểm có thể chỉ là nhiễu, nên 12% → 18% là mức nhỏ nhất đọc được. Tỉ lệ 60/40 ở đây nghiêng về bán hàng, ngược với mức trung bình khoảng 60% thương hiệu/40% kích hoạt mà Binet & Field (IPA) tìm thấy; đây là lựa chọn cho một quý cần số, không phải chuẩn.',
  takeaway:'Bán hàng và thương hiệu cần ngân sách riêng, mục tiêu riêng — đừng đo video kể chuyện bằng số đơn tuần này.',
  apply:'Nghĩ về một thương hiệu bạn biết đang chạy khuyến mãi liên tục. Nói trong 60 giây: nếu họ dừng khuyến mãi, điều gì còn lại giữ khách?',
  mistakes:['Đánh giá chiến dịch thương hiệu bằng số đơn ngay trong tuần phát sóng.','Dồn hết ngân sách vào khuyến mãi vì số liệu đẹp nhanh, rồi phụ thuộc vào giảm giá.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: nếu hãng nước mắm dồn 100% ngân sách vào "mua 2 tặng 1" nhiều quý liền, bạn đoán điều gì dễ xảy ra?',
    options:[{k:'a',t:'Doanh số tăng đều mãi vì khách quen dần với thương hiệu'},{k:'b',t:'Khách chờ khuyến mãi mới mua, dừng giảm giá là đơn tụt'},
             {k:'c',t:'Sàn sẽ ưu tiên hiển thị hãng miễn phí vì bán được nhiều đơn'},{k:'d',t:'Nhận biết thương hiệu tự tăng nhanh hơn làm video kể chuyện'}],
    answer:'b', why:{a:'Khách quen với giá giảm hơn là với thương hiệu.',
      b:'Đúng. Khuyến mãi liên tục dạy khách chờ giá; đơn gắn với khuyến mãi chứ không gắn với tên hãng.',
      c:'Thuật toán sàn có thể ưu tiên sản phẩm bán chạy, nhưng không thay cho lý do khách chọn bạn.',
      d:'Người mua vì giảm giá thường nhớ giá, ít nhớ câu chuyện của hãng.'} },
  { type:'mcq', stem:'Bạn được giao chia 300 triệu giữa khuyến mãi và video kể chuyện. Bạn làm gì?',
    options:[{k:'a',t:'Chia theo tỉ lệ, mỗi phần một mục tiêu và một cách đo riêng'},{k:'b',t:'Dồn hết vào khuyến mãi vì số đơn đo được ngay trong quý này'},
             {k:'c',t:'Chia đôi 150/150 và đo cả hai phần bằng tổng số đơn cuối quý'},{k:'d',t:'Dồn hết vào video vì thương hiệu mạnh rồi thì tự nhiên sẽ có đơn'}],
    answer:'a', why:{a:'Đúng. Mỗi phần phục vụ một mục đích nên cần thước đo đúng với mục đích đó.',
      b:'Thắng quý này nhưng làm hãng lệ thuộc giảm giá ở các quý sau.',
      c:'Đo video bằng số đơn cuối quý sẽ kết luận oan rằng video vô ích.',
      d:'Hãng nhỏ cần dòng tiền; bỏ hẳn bán hàng ngắn hạn là rủi ro.'} },
  { type:'calc', stem:'Khảo sát 300 người trong nhóm khách mục tiêu, tỉ lệ nhớ ra tên hãng tăng từ 12% lên 18%. Có thêm bao nhiêu người nhớ ra tên hãng trong mẫu?',
    unit:'người', ans:18, tol:0.5, wrong:[[6,'NHAM_DIEM_PHAN_TRAM'],[54,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Trước: 12% × 300 = 36 người. Sau: 18% × 300 = 54 người.','Thêm: 54 − 36 = <b>18 người</b> (tăng 6 điểm phần trăm).'] },
  { type:'mcq', stem:'Sau tuần đầu phát video làng nghề, số đơn trên sàn gần như không đổi. Giám đốc bán hàng đòi dừng video. Bạn trả lời thế nào?',
    options:[{k:'a',t:'Đồng ý dừng, vì chiến dịch nào không ra đơn trong tuần đầu là thất bại'},{k:'b',t:'Chuyển tiền video sang khuyến mãi rồi quay lại làm video vào năm sau'},
             {k:'c',t:'Giữ video nhưng gắn thêm mã giảm giá vào để có đơn ngay trong tuần'},{k:'d',t:'Video được đo bằng tỉ lệ nhớ tên cuối quý, chưa đến lúc đánh giá'}],
    answer:'d', why:{a:'Áp thước đo bán hàng lên mục tiêu thương hiệu là đánh giá sai.',
      b:'Làm thương hiệu ngắt quãng thì trí nhớ khách không kịp tích luỹ.',
      c:'Gắn mã giảm giá biến video thành một khuyến mãi khác và làm nhoè mục đích.',
      d:'Đúng. Mục tiêu đã chốt từ đầu; đánh giá theo đúng thước đo và đúng thời điểm.'} },
  { type:'mcq', stem:'Chỉ số nào phù hợp nhất để đo một mục tiêu thương hiệu?',
    options:[{k:'a',t:'Số đơn dùng mã giảm giá trong tuần chạy quảng cáo'},{k:'b',t:'Chi phí mỗi đơn hàng trên sàn thương mại điện tử'},
             {k:'c',t:'Tỉ lệ người trong nhóm mục tiêu nhớ ra tên khi được hỏi'},{k:'d',t:'Số lượt bấm vào đường link mua hàng trong bài đăng'}],
    answer:'c', why:{a:'Đây là chỉ số bán hàng ngắn hạn.',
      b:'Chi phí mỗi đơn đo hiệu quả bán hàng, không đo trí nhớ về thương hiệu.',
      c:'Đúng. Trí nhớ không gợi ý là thước đo cốt lõi của sức mạnh thương hiệu.',
      d:'Lượt bấm đo ý định mua ngay, không đo thương hiệu tích luỹ.'} },
  { type:'mcq', stem:'Một chuỗi trà sữa mới mở 3 cửa hàng, tiền mặt eo hẹp. Cách chia ngân sách nào hợp lý nhất?',
    options:[{k:'a',t:'Phần lớn cho bán hàng tại khu cửa hàng, phần nhỏ đều đặn cho nhận diện'},{k:'b',t:'Dồn tiền cho quảng cáo thương hiệu toàn quốc để đón đầu đối thủ lớn'},
             {k:'c',t:'Dồn tiền cho giảm giá sâu vì chuỗi mới cần đơn trước, thương hiệu sau'},{k:'d',t:'Không chi gì cho marketing, đợi có lãi rồi mới bắt đầu làm thương hiệu'}],
    answer:'a', why:{a:'Đúng. Tiền eo hẹp thì cần dòng tiền trước, nhưng vẫn giữ một phần nhỏ để khách nhớ tên.',
      b:'Quảng cáo toàn quốc cho 3 cửa hàng là tiêu tiền ở nơi khách không thể mua.',
      c:'Giảm giá sâu từ đầu dạy khách rằng giá gốc là giá đắt.',
      d:'Chuỗi mới không ai biết thì khó có lãi để mà chờ.'} },
  { type:'mcq', stem:'Câu nào nói đúng về quan hệ giữa thương hiệu và khuyến mãi?',
    options:[{k:'a',t:'Hai việc đối nghịch: làm thương hiệu thì không được khuyến mãi'},{k:'b',t:'Thương hiệu được nhớ giúp mỗi đồng khuyến mãi sau này kéo đơn tốt hơn'},
             {k:'c',t:'Khuyến mãi đủ lâu thì tự trở thành thương hiệu, không cần làm thêm'},{k:'d',t:'Thương hiệu là việc của hàng cao cấp, hàng phổ thông chỉ đua bằng giá'}],
    answer:'b', why:{a:'Hầu hết thương hiệu lớn làm cả hai, chỉ cần tỉ lệ hợp lý.',
      b:'Đúng. Khi khách đã biết và tin tên hãng, cùng một mức giảm giá sẽ thuyết phục hơn.',
      c:'Khuyến mãi lâu dài tạo thương hiệu "rẻ", không phải lý do chọn bạn khi đối thủ cũng giảm.',
      d:'Nước mắm, mì gói đều là hàng phổ thông và vẫn cần được nhớ tên ở kệ.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:gt06-04', skill:'measure', read:'7 phút', t:'Doanh thu chỉ biết cuối tháng — theo dõi gì mỗi tuần?',
  situation:'Bạn làm marketing cho một trung tâm tiếng Anh thiếu nhi ở Hà Nội. Mục tiêu tháng: 40 học viên đăng ký mới. Nhưng số đăng ký chỉ rõ vào tuần cuối, khi phụ huynh đóng học phí. Tháng trước, đến ngày 25 mới biết hụt, không kịp xoay. Giám đốc hỏi: có cách nào biết sớm hơn không?',
  concept:{ name:'Chỉ số dẫn đầu và chỉ số kết quả',
    body:'<b>Chỉ số kết quả (lagging)</b> cho biết đã đạt hay chưa — doanh thu, số đăng ký — nhưng đến muộn, lúc biết thì đã hết cách sửa. <b>Chỉ số dẫn đầu (leading)</b> đến sớm hơn và có quan hệ ổn định với kết quả — số phụ huynh để lại số điện thoại, số buổi học thử được đặt. Theo dõi chỉ số dẫn đầu hằng tuần giống nhìn đồng hồ xăng khi đang chạy, thay vì chỉ biết hết xăng khi xe dừng.' },
  example:'Số liệu cũ cho thấy khoảng 50% phụ huynh đặt lịch học thử sẽ đến, và 40% người đến học thử sẽ đăng ký. Muốn 40 học viên cần 100 buổi học thử có mặt, tức 200 lịch đặt trong tháng, khoảng 50 lịch mỗi tuần. Hết tuần 1 chỉ có 30 lịch đặt: bạn biết ngay là hụt và còn ba tuần để xoay.',
  takeaway:'Kết quả cho biết đã thắng hay thua; chỉ số dẫn đầu cho biết còn kịp sửa hay không.',
  points:["Chỉ số dẫn đầu hoạt động nhờ khâu trung gian có tỉ lệ ổn định. Khi hai tỉ lệ 50% và 40% giữ gần nguyên, số lịch đặt tuần 1 giúp suy ra kết quả.","Tuần là nhịp vừa đủ: ngắn hơn thì số quá nhỏ và dao động, dài hơn thì muộn sửa. Mốc 50 lịch mỗi tuần biến mục tiêu tháng thành việc kiểm tra mỗi thứ Hai.","Chỉ số tốt là chỉ số đội của bạn tác động được. Số lịch đặt đổi nhờ nhắc, nhờ ưu đãi buổi thử, còn doanh thu cuối tháng chỉ biết sau khi việc đã xong."],
  counter:"Chỉ số dẫn đầu mất tác dụng khi tỉ lệ ở giữa thay đổi. Giả sử trung tâm đổi giáo viên buổi học thử, khiến con số 40% người đến thử sẽ đăng ký không còn đúng. Số lịch đặt vẫn đủ 50 mỗi tuần nhưng đăng ký vẫn hụt. Dấu hiệu là chỉ số dẫn đầu đạt mốc mà kết quả lệch liền hai ba tuần. Lúc đó cần đo lại tỉ lệ giữa các bước.",
  deeper:"Người làm nghề nhớ rằng chỉ số dẫn đầu là một ước lượng, nên cần đối chiếu với kết quả sau mỗi kỳ để chỉnh lại tỉ lệ. Đánh đổi là theo dõi nhiều chỉ số thì tốn công và dễ nhiễu, nên chỉ giữ một hai chỉ số sát kết quả nhất. Tín hiệu nên theo dõi là độ lệch giữa số lịch đặt và số buổi thử có mặt thật, vì đó là chỗ phụ huynh rơi ra. Khái niệm kề cận là phễu chuyển đổi. Phép kiểm tra trong tuần: lấy số liệu ba tháng gần nhất, tính lại hai tỉ lệ 50% và 40% xem chúng có giữ gần nhau không.",
  apply:'Chọn một mục tiêu kết quả bạn biết. Nói trong 60 giây: hành động nào của khách xảy ra trước kết quả ít nhất hai tuần, và bạn đếm nó thế nào.',
  mistakes:['Chỉ báo cáo doanh thu nên luôn biết hụt khi đã quá muộn.','Chọn chỉ số dẫn đầu không có quan hệ thật với kết quả, như lượt thích bài.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: với mục tiêu 40 học viên mới, bạn đoán con số nào báo hiệu sớm nhất là tháng này có hụt?',
    options:[{k:'a',t:'Tổng doanh thu học phí thu được vào cuối tháng'},{k:'b',t:'Số lượt thích trên bài đăng tuyển sinh của trung tâm'},
             {k:'c',t:'Số giáo viên đang giảng dạy tại trung tâm trong tháng'},{k:'d',t:'Số lịch học thử phụ huynh đặt mỗi tuần'}],
    answer:'d', why:{a:'Đây là chỉ số kết quả, biết thì đã muộn.',
      b:'Lượt thích đến sớm nhưng quan hệ với việc đăng ký học rất lỏng.',
      c:'Số giáo viên là năng lực phục vụ, không báo hiệu nhu cầu.',
      d:'Đúng. Đặt lịch học thử xảy ra sớm và là bước ngay trước khi đăng ký.'} },
  { type:'mcq', stem:'Hết tuần 1 chỉ có 30 lịch đặt học thử so với mức cần khoảng 50. Bạn làm gì?',
    options:[{k:'a',t:'Chờ hết tháng xem kết quả rồi mới rút kinh nghiệm cho tháng sau'},{k:'b',t:'Báo ngay, tìm nguyên nhân và thêm nguồn đặt lịch cho ba tuần còn lại'},
             {k:'c',t:'Hạ mục tiêu tháng xuống 24 học viên cho khớp với tốc độ tuần đầu tiên'},{k:'d',t:'Giảm học phí 30% cho phụ huynh đăng ký trong tuần để kéo đủ học viên'}],
    answer:'b', why:{a:'Chờ đến cuối tháng là lặp lại đúng vấn đề của tháng trước.',
      b:'Đúng. Mục đích của chỉ số dẫn đầu là hành động khi còn thời gian.',
      c:'Một tuần chưa đủ để kết luận; trước khi hạ mục tiêu cần thử bù đã.',
      d:'Giảm giá sâu trước khi hiểu nguyên nhân có thể làm mất lãi mà chưa chắc đúng chỗ.'} },
  { type:'calc', stem:'Mục tiêu 40 học viên. 40% người đến học thử sẽ đăng ký, 50% người đặt lịch sẽ đến. Cần bao nhiêu lịch đặt học thử trong tháng?',
    unit:'lịch', ans:200, tol:1, wrong:[[100,'QUEN_TI_LE_CHUYEN_DOI'],[8,'NGUOC_TAN_SUAT']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Người đến học thử cần có = 40 ÷ 0,4 = 100.','Lịch đặt cần có = 100 ÷ 0,5 = <b>200 lịch</b>.'] },
  { type:'mcq', stem:'Một chỉ số dẫn đầu tốt cần có đặc điểm gì?',
    options:[{k:'a',t:'Đến sớm và có quan hệ ổn định với kết quả cuối cùng'},{k:'b',t:'Càng nhiều càng tốt, theo dõi hàng chục chỉ số một lúc'},
             {k:'c',t:'Phải là con số lớn để báo cáo nhìn ấn tượng với sếp'},{k:'d',t:'Dễ lấy ngay từ trang quản trị nền tảng quảng cáo'}],
    answer:'a', why:{a:'Đúng. Sớm để kịp sửa, ổn định để tin được là nó báo đúng.',
      b:'Quá nhiều chỉ số làm loãng sự chú ý; hai ba chỉ số đúng là đủ.',
      c:'Độ lớn của con số không quyết định giá trị dự báo.',
      d:'Dễ lấy là tiện, nhưng nếu không liên quan đến kết quả thì vô dụng.'} },
  { type:'mcq', stem:'Một shop quần áo online thấy lượt thích tăng gấp đôi nhưng đơn không đổi suốt ba tháng. Kết luận nào hợp lý?',
    options:[{k:'a',t:'Đơn sẽ tăng muộn hơn, cứ tiếp tục đẩy lượt thích lên cao nữa'},{k:'b',t:'Lượt thích chưa phải chỉ số dẫn đầu tốt cho đơn của shop này'},
             {k:'c',t:'Khách đang tiết kiệm tiền, không liên quan gì đến cách đo lường'},{k:'d',t:'Cần đổi nền tảng vì nền tảng hiện tại không ra được đơn nào nữa'}],
    answer:'b', why:{a:'Ba tháng không có quan hệ là bằng chứng đủ để nghi ngờ chỉ số.',
      b:'Đúng. Chỉ số dẫn đầu phải đi cùng kết quả; không đi cùng thì chọn chỉ số khác, như lượt nhắn hỏi size.',
      c:'Có thể, nhưng đó là giả định chưa kiểm; dữ kiện đang nói về chỉ số.',
      d:'Đổi nền tảng khi chưa biết chỉ số nào đúng là giải quyết sai vấn đề.'} },
  { type:'mcq', stem:'Với một nhà hàng nhận đặt tiệc cưới, chỉ số nào là chỉ số dẫn đầu phù hợp nhất cho doanh thu tiệc quý sau?',
    options:[{k:'a',t:'Doanh thu tiệc cưới đã thu được trong quý hiện tại'},{k:'b',t:'Điểm đánh giá trung bình của nhà hàng trên Google Maps'},
             {k:'c',t:'Số cặp đôi đến xem sảnh và nhận báo giá mỗi tuần'},{k:'d',t:'Số món mới đầu bếp đưa vào thực đơn tiệc trong năm'}],
    answer:'c', why:{a:'Đây là kết quả của quý này, không báo hiệu quý sau.',
      b:'Điểm đánh giá ảnh hưởng dài hạn nhưng thay đổi chậm và không báo số tiệc cụ thể.',
      c:'Đúng. Xem sảnh và nhận báo giá là bước ngay trước khi đặt cọc tiệc.',
      d:'Món mới là đầu vào sản phẩm, không phải tín hiệu nhu cầu.'} },
  { type:'mcq', stem:'Vì sao chỉ theo dõi chỉ số kết quả là nguy hiểm với mục tiêu tháng?',
    options:[{k:'a',t:'Vì chỉ số kết quả thường bị nền tảng quảng cáo đo sai lệch nhiều'},{k:'b',t:'Vì chỉ số kết quả khó nối thẳng về mục tiêu kinh doanh'},
             {k:'c',t:'Vì giám đốc thường không hiểu cách đọc các chỉ số kết quả'},{k:'d',t:'Vì khi nó báo hụt thì thường không còn thời gian để sửa'}],
    answer:'d', why:{a:'Chỉ số kết quả như doanh thu thường đo khá chính xác; vấn đề là thời điểm.',
      b:'Chính chỉ số kết quả là thứ nối thẳng với kinh doanh.',
      c:'Doanh thu là con số ai cũng đọc được.',
      d:'Đúng. Chỉ số kết quả đúng nhưng đến muộn — như tháng trước của trung tâm.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:gt06-05', skill:'measure', read:'6 phút', t:'Team 4 người, 12 chỉ số — nên nhìn con số nào trước?',
  situation:'Team marketing 4 người của một app đặt lịch cắt tóc ở TP.HCM báo cáo hằng tuần 12 chỉ số: lượt tải, người dùng đăng ký, follower, lượt xem video, CTR quảng cáo… Mỗi người tối ưu chỉ số của mình. Lượt tải tăng 40% trong quý nhưng số lịch cắt tóc thật gần như không đổi. Sếp hỏi: rốt cuộc team đang cùng đẩy về đâu?',
  concept:{ name:'Chỉ số chính (north star metric)',
    body:'Chỉ số chính là <b>một con số</b> thể hiện giá trị khách thật sự nhận được, và nếu nó tăng bền thì thường dự báo tốt doanh thu. Nó cần một <b>chỉ số đối trọng</b> (như tỉ lệ huỷ lịch) vì có thể bị đẩy lên bằng cách làm hỏng thứ khác, và một cây đầu vào: lịch hoàn thành = lượt tải × % đặt lịch × % hoàn thành. Mọi chỉ số khác trở thành chỉ số phụ, được xem xét ở mức nó giúp chỉ số chính ra sao. Chỉ số chính tốt thường đếm hành vi có giá trị lặp lại — lịch đặt được hoàn thành, đơn giao thành công — chứ không đếm lượt tải hay lượt xem, vì những thứ đó tăng được mà khách chẳng nhận gì.' },
  example:'Team chọn chỉ số chính: số lịch cắt tóc hoàn thành mỗi tuần, hiện 1.200. Lượt tải chỉ còn giá trị khi người tải đặt lịch. Soi lại, người tải mới chỉ 10% đặt lịch trong 30 ngày. Nâng tỉ lệ đó lên 15% với 8.000 lượt tải mỗi tháng là thêm 400 người đặt lịch — so với 320 người nếu kéo thêm 40% lượt tải, mà không phải mua thêm lượt tải.',
  takeaway:'Một chỉ số chính cho cả team: đếm giá trị khách nhận được, không đếm hoạt động của team.',
  apply:'Chọn một app hoặc cửa hàng bạn dùng thường xuyên. Nói trong 60 giây: một con số nào thể hiện rõ nhất việc khách nhận được giá trị ở đó.',
  mistakes:['Chọn lượt tải hoặc người đăng ký làm chỉ số chính vì nó tăng nhanh.','Mỗi người trong team tự chọn một chỉ số riêng và tối ưu tách rời nhau.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: với app đặt lịch cắt tóc, bạn đoán con số nào nên là chỉ số chính của cả team?',
    options:[{k:'a',t:'Lượt tải app mỗi tháng trên cả hai kho ứng dụng'},{k:'b',t:'Số follower của app trên các mạng xã hội'},
             {k:'c',t:'Số lịch cắt tóc được hoàn thành mỗi tuần'},{k:'d',t:'Tỉ lệ nhấp trung bình mỗi quảng cáo'}],
    answer:'c', why:{a:'Lượt tải tăng mà không đặt lịch thì khách chưa nhận gì.',
      b:'Follower không cho biết ai dùng app để cắt tóc.',
      c:'Đúng. Lịch hoàn thành là lúc khách nhận giá trị và app có doanh thu.',
      d:'CTR là chỉ số hiệu quả quảng cáo, một mắt xích rất xa kết quả.'} },
  { type:'mcq', stem:'Bạn đề xuất team bỏ bớt báo cáo 12 chỉ số. Bạn chọn cách tổ chức nào?',
    options:[{k:'a',t:'Giữ đủ 12 chỉ số nhưng tô màu đỏ những chỉ số đang giảm để chú ý'},{k:'b',t:'Một chỉ số chính ở trên cùng, dưới là 2–3 chỉ số phụ nối vào nó'},
             {k:'c',t:'Mỗi người tự chọn một chỉ số quan trọng nhất trong phần việc của mình'},{k:'d',t:'Chỉ báo cáo doanh thu, bỏ hết các chỉ số khác cho team đỡ rối mắt'}],
    answer:'b', why:{a:'Tô màu không giải quyết việc team kéo về nhiều hướng.',
      b:'Đúng. Một đích chung, và các chỉ số phụ cho biết đòn bẩy nào đang đẩy đích.',
      c:'Đây chính là tình trạng hiện tại: mỗi người tối ưu phần mình, cả team không cùng hướng.',
      d:'Chỉ nhìn doanh thu thì biết kết quả nhưng không biết sửa ở đâu.'} },
  { type:'calc', stem:'Mỗi tháng có 8.000 lượt tải. Tỉ lệ người tải đặt lịch trong 30 ngày tăng từ 10% lên 15%. Có thêm bao nhiêu người đặt lịch mỗi tháng?',
    unit:'người', ans:400, tol:1, wrong:[[5,'NHAM_DIEM_PHAN_TRAM'],[1200,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Trước: 8.000 × 10% = 800 người. Sau: 8.000 × 15% = 1.200 người.','Thêm: 1.200 − 800 = <b>400 người</b>.'] },
  { type:'mcq', stem:'Một sàn đồ cũ chọn "số tin đăng bán mới mỗi tuần" làm chỉ số chính. Rủi ro là gì?',
    options:[{k:'a',t:'Tin đăng tăng mà không bán được thì người bán nản và rời sàn'},{k:'b',t:'Tin đăng khó đếm chính xác nên số liệu báo cáo sẽ hay bị sai'},
             {k:'c',t:'Người mua sẽ phàn nàn vì sàn có quá nhiều lựa chọn để chọn'},{k:'d',t:'Chỉ số này chỉ phù hợp với sàn đồ mới, không hợp với đồ cũ'}],
    answer:'a', why:{a:'Đúng. Giá trị chỉ đến khi giao dịch thành công; số giao dịch hoàn tất là lựa chọn tốt hơn.',
      b:'Tin đăng đếm rất dễ trong hệ thống.',
      c:'Nhiều lựa chọn chưa phải vấn đề chính; vấn đề là đếm hoạt động chứ không đếm giá trị.',
      d:'Loại hàng không quyết định; vấn đề là chỉ số không đo giá trị nhận được.'} },
  { type:'mcq', stem:'Sau đợt giảm 50% phí đặt lịch, lịch hoàn thành mỗi tuần tăng 30% nhưng tỉ lệ huỷ lịch từ 8% lên 16%. Bạn đọc kết quả thế nào?',
    options:[{k:'a',t:'Thành công, vì chỉ số chính tăng và huỷ lịch chỉ là biến động thường'},{k:'b',t:'Thất bại, vì huỷ lịch tăng gấp đôi nên phải dừng ngay đợt giảm giá'},
             {k:'c',t:'Bỏ chỉ số huỷ lịch khỏi báo cáo để cả team chỉ tập trung một con số'},{k:'d',t:'Chưa kết luận: tăng có thể do khách chạy theo giá, xem họ có quay lại'}],
    answer:'d', why:{a:'Huỷ lịch tăng gấp đôi là tín hiệu chỉ số chính đang được đẩy bằng cách đổi chất lượng khách.',
      b:'Lịch hoàn thành vẫn tăng 30%; dừng ngay là phản ứng thái quá khi chưa biết khách có quay lại không.',
      c:'Bỏ chỉ số đối trọng đúng lúc nó báo động là che mất vấn đề.',
      d:'Đúng. Chỉ số đối trọng cho thấy cái giá của mức tăng; cần xem khách quay lại trước khi nhân rộng.'} },
  { type:'mcq', stem:'Một tiệm giặt sấy theo tuần muốn chọn chỉ số chính. Lựa chọn nào tốt nhất?',
    options:[{k:'a',t:'Số lượt ghé fanpage mỗi tuần để xem bảng giá dịch vụ giặt'},{k:'b',t:'Số lượt gửi đồ lặp lại của khách quen mỗi tuần, theo dõi liên tục'},
             {k:'c',t:'Số tờ rơi đã phát trong khu dân cư xung quanh tiệm giặt'},{k:'d',t:'Số máy giặt công nghiệp tiệm đầu tư thêm trong năm nay'}],
    answer:'b', why:{a:'Ghé fanpage chưa phải là dùng dịch vụ.',
      b:'Đúng. Khách lặp lại đều đặn cho thấy họ nhận giá trị và tạo doanh thu ổn định.',
      c:'Tờ rơi là hoạt động của tiệm, không phải giá trị khách nhận.',
      d:'Máy móc là năng lực phục vụ, không đo khách.'} },
  { type:'mcq', stem:'Sau khi chọn chỉ số chính, việc gì dễ bị bỏ qua nhất?',
    options:[{k:'a',t:'In chỉ số chính ra treo tường cho cả công ty cùng nhìn thấy'},{k:'b',t:'Thay công cụ đo lường cũ bằng một phần mềm mới đắt tiền hơn'},
             {k:'c',t:'Nối việc của từng người vào một chỉ số phụ đẩy chỉ số chính'},{k:'d',t:'Đặt mục tiêu tăng chỉ số chính gấp đôi ngay trong tháng đầu tiên'}],
    answer:'c', why:{a:'Treo tường giúp nhớ, nhưng không cho mỗi người biết mình tác động thế nào.',
      b:'Công cụ mới không cần thiết nếu cách đo cũ đếm được chỉ số chính.',
      c:'Đúng. Không có cầu nối này thì mỗi người vẫn làm việc cũ, chỉ đổi tên báo cáo.',
      d:'Mục tiêu gấp đôi tháng đầu thường không khả thi và làm team mất tin vào chỉ số.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:gt06-06', skill:'measure', read:'7 phút', t:'Tăng khách hay tăng lãi — khi hai mục tiêu giành nhau?',
  situation:'Một chuỗi 5 tiệm bánh mì ở Cần Thơ đặt cùng lúc hai mục tiêu cho quý: tăng 30% số khách và tăng biên lãi gộp từ 40% lên 45%. Team marketing định chạy "giảm 20% cho khách lần đầu" để kéo khách. Kế toán phản đối: giảm giá thì biên lãi đi xuống, sao đạt 45%?',
  concept:{ name:'Mục tiêu mâu thuẫn và thứ tự ưu tiên',
    body:'Hai mục tiêu có thể kéo ngược nhau: kéo khách thường cần giá hấp dẫn, tăng lãi thường cần giá cao hoặc chi ít. Đặt cả hai ngang nhau thì team sẽ chọn cái dễ đo nhất. Cách xử lý: chọn <b>một mục tiêu chính</b> và biến cái kia thành <b>giới hạn</b> — ví dụ "tăng khách 30%, với điều kiện biên lãi không xuống dưới 38%". Giới hạn cho team biết được hy sinh bao nhiêu, không hơn.' },
  example:'Bánh 25.000 đồng, giá vốn 15.000 đồng, lãi gộp 10.000 đồng (40%). Giảm 20% còn 20.000 đồng thì lãi gộp chỉ 5.000 đồng — mỗi chiếc giảm giá mất nửa phần lãi. Nếu 1/5 số bánh bán ra là bánh giảm giá, biên lãi chung còn 37,5% (45.000 ÷ 120.000 trên mỗi 5 chiếc), thủng giới hạn 38%. Team đổi sang tặng ly trà đá giá vốn 2.000 đồng cho khách lần đầu: lãi mỗi đơn còn 8.000 đồng; với cùng tỉ trọng 1/5, biên lãi chung khoảng 38,4% — vừa đủ giữ giới hạn.',
  takeaway:'Hai mục tiêu giành nhau thì chọn một làm đích, biến cái kia thành giới hạn có con số.',
  points:["Giới hạn biến một cuộc tranh luận thành phép tính. Khi biên lãi tối thiểu là 38%, mỗi ưu đãi chỉ cần trả lời: nó có kéo biên lãi chung xuống dưới mức đó không.","Giảm giá cắt thẳng vào lãi vì giá vốn không đổi. Giảm 20% trên 25.000 đồng là 5.000 đồng, nhưng với lãi gộp 10.000 đồng thì <b>mất nửa phần lãi</b> chứ không phải 20%.","Quà tặng có giá vốn thấp giữ nguyên giá bán nên bảo vệ biên lãi. Khách vẫn cảm nhận được ưu đãi, còn tiệm chỉ trả phần giá vốn của món tặng."],
  counter:"Một đích một giới hạn sẽ sai khi hai thứ phụ thuộc nhau quá chặt. Giả sử các tiệm bánh mì ở Cần Thơ nằm trong khu nhiều đối thủ giảm giá, khách chỉ đến khi ưu đãi sâu. Khi đó giữ biên lãi 38% có thể khiến số khách gần như không nhúc nhích. Dấu hiệu là ưu đãi nhẹ không kéo được khách sau vài tuần thử. Lúc ấy cần hỏi lại chủ tiệm.",
  deeper:"Người làm nghề hỏi thêm: giới hạn 38% là con số kỹ thuật hay là mức chủ tiệm thật sự không nhượng. Đánh đổi là giới hạn quá chặt sẽ giết ý tưởng, quá lỏng thì mất ý nghĩa. Tín hiệu nên theo dõi là biên lãi chung theo tuần, không đợi hết quý, vì khuyến mãi ăn vào lãi ngay từ tuần đầu. Khái niệm kề cận là giá trị vòng đời của khách mới: khách lần đầu quay lại mua tiếp mới bù được phần lãi đã hy sinh. Phép kiểm tra trong tuần: tính biên lãi của một ưu đãi đang chạy bằng cách nhân tỉ trọng đơn khuyến mãi với lãi mỗi đơn của nó.",
  apply:'Nghĩ về một cửa hàng đang muốn vừa đông khách vừa lãi cao. Nói trong 60 giây: bạn chọn mục tiêu nào làm đích, đặt giới hạn gì cho mục tiêu còn lại.',
  mistakes:['Đặt hai mục tiêu kéo ngược nhau mà không nói cái nào ưu tiên.','Tính giảm giá theo phần trăm doanh thu mà quên nó ăn vào lãi gộp nặng hơn nhiều.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: bánh 25.000 đồng, giá vốn 15.000 đồng. Giảm giá 20% làm lãi gộp mỗi chiếc giảm khoảng bao nhiêu?',
    options:[{k:'a',t:'Giảm 20%, đúng bằng mức giảm giá ghi trên bảng'},{k:'b',t:'Giảm khoảng 10%, vì giá vốn gánh bớt một phần'},
             {k:'c',t:'Giảm một nửa, từ 10.000 xuống 5.000 đồng'},{k:'d',t:'Không đổi mấy vì khách đông sẽ bù lại ngay'}],
    answer:'c', why:{a:'Giảm 5.000 đồng trên giá bán là giảm 20% doanh thu nhưng giảm 50% lãi gộp.',
      b:'Giá vốn không đổi, nên toàn bộ phần giảm giá trừ thẳng vào lãi.',
      c:'Đúng. 5.000 đồng giảm giá lấy mất nửa phần lãi 10.000 đồng.',
      d:'Khách đông bù được tổng lãi chỉ khi số lượng tăng đủ lớn; lãi mỗi chiếc vẫn mất một nửa.'} },
  { type:'mcq', stem:'Kế toán và marketing tranh cãi về hai mục tiêu. Bạn sửa cách đặt mục tiêu thế nào?',
    options:[{k:'a',t:'Chọn tăng khách làm đích, biến biên lãi thành giới hạn có con số cụ thể'},{k:'b',t:'Giữ nguyên cả hai mục tiêu ngang nhau và để mỗi phòng tự lo phần mình'},
             {k:'c',t:'Bỏ hẳn mục tiêu biên lãi trong quý này để marketing được tự do giảm giá'},{k:'d',t:'Chuyển cả hai mục tiêu sang cho quý sau khi có thêm số liệu đầy đủ hơn'}],
    answer:'a', why:{a:'Đúng. Một đích, một giới hạn: team biết được phép hy sinh lãi tới đâu.',
      b:'Mỗi phòng lo phần mình là cách để hai phòng triệt tiêu nhau.',
      c:'Bỏ hẳn giới hạn thì có thể đông khách mà lỗ.',
      d:'Hoãn không giải quyết mâu thuẫn, chỉ đẩy nó đi.'} },
  { type:'calc', stem:'Khuyến mãi tặng ly trà đá giá vốn 2.000 đồng cho khách mua bánh 25.000 đồng, giá vốn bánh 15.000 đồng. Lãi gộp mỗi đơn khuyến mãi là bao nhiêu đồng?',
    unit:'đồng', ans:8000, tol:1, wrong:[[10000,'QUEN_CHI_PHI_KHUYEN_MAI'],[5000,'SAI_TINH_TOAN']], errors:['QUEN_CHI_PHI_KHUYEN_MAI'],
    steps:['Lãi gộp bánh = 25.000 − 15.000 = 10.000 đồng.','Trừ quà tặng: 10.000 − 2.000 = <b>8.000 đồng</b>.'] },
  { type:'mcq', stem:'Vì sao đặt hai mục tiêu mâu thuẫn ngang hàng lại nguy hiểm?',
    options:[{k:'a',t:'Vì nền tảng quảng cáo không cho phép chạy hai mục tiêu song song'},{k:'b',t:'Vì hai mục tiêu thì báo cáo cuối quý sẽ dài gấp đôi so với bình thường'},
             {k:'c',t:'Vì sếp sẽ không nhớ nổi quá một mục tiêu cho mỗi quý kinh doanh'},{k:'d',t:'Vì team sẽ tự chọn cái dễ đạt, và cái còn lại bị hy sinh ngầm'}],
    answer:'d', why:{a:'Chuyện nền tảng không liên quan đến mục tiêu kinh doanh.',
      b:'Độ dài báo cáo không phải vấn đề.',
      c:'Nhớ được hay không không phải lý do chính.',
      d:'Đúng. Không có thứ tự ưu tiên thì sự hy sinh xảy ra mà không ai quyết định.'} },
  { type:'mcq', stem:'Một spa muốn tăng khách mới nhưng giữ lãi. Cách kéo khách nào ít ăn vào lãi nhất?',
    options:[{k:'a',t:'Giảm 50% gói liệu trình đầu tiên cho khách mới đến spa'},{k:'b',t:'Tặng thêm 15 phút massage đầu vào khung giờ vắng khách'},
             {k:'c',t:'Giảm 30% các dịch vụ vào cuối tuần khi spa đông khách'},{k:'d',t:'Hoàn tiền nếu khách không hài lòng, không hỏi lý do'}],
    answer:'b', why:{a:'Giảm một nửa gói lớn là mất phần lớn lãi của lần đầu.',
      b:'Đúng. Thời gian giờ vắng gần như không tốn thêm chi phí, mà khách vẫn thấy được lợi.',
      c:'Giảm giá lúc đông là cho đi lãi trên khách vốn đã đến.',
      d:'Hoàn tiền không điều kiện có thể hợp một số ngành, nhưng rủi ro mất lãi cao và khó kiểm soát.'} },
  { type:'mcq', stem:'Mục tiêu nào được viết đúng kiểu "một đích, một giới hạn"?',
    options:[{k:'a',t:'Tăng khách 30% và tăng biên lãi lên 45% trong cùng một quý'},{k:'b',t:'Tăng khách càng nhiều càng tốt, lãi tính sau khi có đủ khách'},
             {k:'c',t:'Tăng biên lãi lên 45%, chấp nhận mất bớt khách cũ'},{k:'d',t:'Tăng khách 30% trong quý, biên lãi không dưới 38%'}],
    answer:'d', why:{a:'Hai đích ngang hàng — chính kiểu gây mâu thuẫn.',
      b:'Không có giới hạn, và "càng nhiều càng tốt" không đo được.',
      c:'Chỉ có một đích là lãi, còn số khách thì không có mức chặn; thiếu giới hạn ở chiều ngược lại.',
      d:'Đúng. Đích rõ, giới hạn có con số.'} },
  { type:'mcq', stem:'Nếu tăng khách đã đạt 30% nhưng biên lãi rơi xuống 36%, dưới giới hạn 38%, nên đánh giá thế nào?',
    options:[{k:'a',t:'Thành công vì đích chính đã đạt đủ, giới hạn chỉ là phụ'},{k:'b',t:'Chưa đạt, vì giới hạn là điều kiện bắt buộc của mục tiêu'},
             {k:'c',t:'Thành công một nửa, cứ lấy trung bình hai con số là được'},{k:'d',t:'Lỗi của kế toán vì đã không cảnh báo sớm cho marketing'}],
    answer:'b', why:{a:'Giới hạn chính là điều kiện để đích được tính là đạt.',
      b:'Đúng. Đạt đích mà thủng giới hạn nghĩa là đổi lấy kết quả bằng cái giá đã được cấm.',
      c:'Lấy trung bình che mất đúng chỗ cần sửa.',
      d:'Theo dõi giới hạn là việc của người chạy chương trình, không đẩy sang bộ phận khác.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:gt06-07', skill:'measure', read:'7 phút', t:'Mở shop mới, chưa có số năm trước — mục tiêu đặt từ đâu?',
  situation:'Bạn cùng người bạn mở một shop bán hạt dinh dưỡng online, bắt đầu từ tháng sau. Nhà đầu tư nhỏ góp vốn hỏi: "Tháng đầu mục tiêu bao nhiêu đơn?" Không có số liệu năm trước, không biết tỉ lệ chuyển đổi của mình. Bạn định nói đại "500 đơn" cho có khí thế.',
  concept:{ name:'Đặt mục tiêu khi chưa có dữ liệu',
    body:'Không có dữ liệu cũ thì mượn <b>dữ liệu tương tự</b> và <b>năng lực thực tế</b>. Ước từ hai phía: phía cầu (ngân sách ÷ chi phí mỗi lượt nhấp × tỉ lệ chuyển đổi tham khảo) và phía cung (mỗi ngày đóng gói được bao nhiêu đơn). Lấy con số nhỏ hơn làm trần. Đặt ba kịch bản (tỉ lệ mua thấp, cơ sở, cao): cam kết mốc thấp, mốc cao là tham vọng. Kiểm thêm chi phí mỗi đơn so với lãi gộp mỗi đơn để biết tháng đầu lỗ bao nhiêu. Rồi gọi đó là <b>mục tiêu học</b>: tháng đầu mục đích chính là đo được các tỉ lệ thật, để tháng sau đặt mục tiêu có căn cứ.' },
  example:'Ngân sách 15 triệu, ước chi phí mỗi lượt nhấp 3.000 đồng → 5.000 lượt vào trang. Tỉ lệ mua tham khảo từ một shop tương tự khoảng 2%, nên đặt ba kịch bản: 1% → 50 đơn, 2% → 100 đơn, 3% → 150 đơn. Phía cung, hai người đóng tối đa 300 đơn mỗi tháng nên chưa bị chặn. Giả sử (số minh hoạ) đơn trung bình 250.000 đồng, lãi gộp 40% tức 100.000 đồng mỗi đơn. Ở mức 100 đơn, chi phí mỗi đơn là 150.000 đồng, cao hơn lãi gộp: tháng đầu lỗ khoảng 5 triệu trước chi phí khác. Cam kết 50 đơn, kỳ vọng 100, và coi phần lỗ là học phí để đo tỉ lệ mua thật.',
  takeaway:'Chưa có số thì ước một khoảng thấp–cơ sở–cao từ ngân sách và năng lực, cam kết mốc thấp, và coi tháng đầu là tháng đo.',
  apply:'Giả sử bạn mở một shop nhỏ với 10 triệu tiền quảng cáo. Nói trong 60 giây cách bạn ước số đơn tháng đầu, dùng chi phí mỗi lượt nhấp và tỉ lệ mua bạn giả định.',
  mistakes:['Đặt một con số cho có khí thế, không từ phép tính nào.','Quên kiểm năng lực phục vụ, ra đơn nhiều hơn khả năng đóng gói và giao.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: không có số năm trước, bạn đoán nên bắt đầu ước mục tiêu tháng đầu từ đâu?',
    options:[{k:'a',t:'Lấy mục tiêu của đối thủ lớn nhất ngành rồi chia đôi cho an toàn'},{k:'b',t:'Chọn một con số tròn đủ lớn để cả team có động lực cố gắng'},
             {k:'c',t:'Từ ngân sách, chi phí mỗi lượt nhấp và tỉ lệ mua tham khảo'},{k:'d',t:'Đợi hết tháng đầu rồi mới đặt mục tiêu, cứ làm trước đã'}],
    answer:'c', why:{a:'Quy mô đối thủ lớn khác xa shop mới; chia đôi vẫn không có căn cứ.',
      b:'Con số lấy cảm hứng dễ làm team nản ngay từ tháng đầu.',
      c:'Đúng. Ba con số này cho một ước tính có lý lẽ, dù chưa chính xác.',
      d:'Không có mục tiêu thì cũng không biết tháng đầu đang tốt hay xấu.'} },
  { type:'mcq', stem:'Nhà đầu tư hỏi con số tháng đầu. Bạn chọn cách trả lời nào?',
    options:[{k:'a',t:'Từ 50 đến 150 đơn, cam kết 50, kèm cách tính và việc cần đo thật'},{k:'b',t:'500 đơn cho có khí thế, thiếu thì tháng sau sẽ cố gắng bù đắp lại'},
             {k:'c',t:'Chưa đặt con số, đợi chạy thử một tháng rồi mới tính cho chắc ăn'},{k:'d',t:'300 đơn vì đó là số tối đa hai người có thể đóng gói trong tháng'}],
    answer:'a', why:{a:'Đúng. Có khoảng và mốc cam kết, minh bạch cách tính, nói rõ tháng đầu để học.',
      b:'Không có phép tính nào dẫn tới 500; hụt xa sẽ làm mất lòng tin nhà đầu tư.',
      c:'Đã đủ dữ kiện để ước tính có căn cứ; chờ một tháng mới đưa số là né câu hỏi của nhà đầu tư.',
      d:'Năng lực đóng gói là trần phía cung, không phải con số cầu sẽ đạt.'} },
  { type:'calc', stem:'Một shop khác có ngân sách 12 triệu đồng, chi phí mỗi lượt nhấp ước 4.000 đồng, tỉ lệ mua tham khảo 2,5%. Ước bao nhiêu đơn trong tháng?',
    unit:'đơn', ans:75, tol:1, wrong:[[3000,'QUEN_TI_LE_CHUYEN_DOI'],[750,'NHAM_DIEM_PHAN_TRAM']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Lượt vào trang = 12.000.000 ÷ 4.000 = 3.000.','Số đơn = 3.000 × 2,5% = <b>75 đơn</b>.'] },
  { type:'mcq', stem:'Mỗi đơn lãi gộp 100.000 đồng nhưng chi phí quảng cáo mỗi đơn dự kiến 150.000 đồng. Tháng đầu nên xử lý thế nào?',
    options:[{k:'a',t:'Dừng luôn vì mỗi đơn đều lỗ, tháng đầu cũng không nên chịu lỗ'},{k:'b',t:'Coi phần lỗ là học phí, đặt trần chi, đo tỉ lệ mua và khách quay lại'},
             {k:'c',t:'Tăng giá bán 50% ngay cho cân bằng, chưa cần kiểm khách có chịu không'},{k:'d',t:'Bỏ qua chênh lệch vì doanh thu 250.000 mỗi đơn đã lớn hơn 150.000'}],
    answer:'b', why:{a:'Chưa có tỉ lệ mua thật nên chưa biết lỗ có kéo dài; dừng sớm là bỏ mất dữ liệu cần đo.',
      b:'Đúng. Lỗ có trần và có mục đích đo thì là chi phí học; không có trần thì là đốt tiền.',
      c:'Tăng giá mà chưa kiểm phản ứng của khách có thể làm tỉ lệ mua tụt thêm, lỗ nặng hơn.',
      d:'So doanh thu với chi phí quảng cáo là quên giá vốn; thứ cần so là lãi gộp.'} },
  { type:'mcq', stem:'Hết tháng đầu, shop đạt 60 đơn thay vì 100. Tỉ lệ mua thật là 1,2%. Bước tiếp theo hợp lý nhất?',
    options:[{k:'a',t:'Kết luận shop thất bại, nên tìm mặt hàng khác thay thế ngay'},{k:'b',t:'Giữ mục tiêu 100 cho tháng sau và bảo team cố gắng nhiều hơn'},
             {k:'c',t:'Tăng gấp đôi ngân sách quảng cáo để bù cho phần đơn còn thiếu'},{k:'d',t:'Dùng 1,2% làm căn cứ mới, tìm cách nâng tỉ lệ mua trước khi tăng tiền'}],
    answer:'d', why:{a:'Tháng đầu là tháng đo; một tháng chưa đủ để bỏ cả mặt hàng.',
      b:'Giữ nguyên con số mà không đổi giả định là lặp lại sai lầm.',
      c:'Tỉ lệ mua đang thấp; đổ thêm tiền vào trang chưa tối ưu là tốn gấp đôi.',
      d:'Đúng. Giờ đã có dữ liệu thật để đặt mục tiêu và biết chỗ cần sửa.'} },
  { type:'mcq', stem:'"Mục tiêu học" cho tháng đầu nghĩa là gì?',
    options:[{k:'a',t:'Mục tiêu đo được các tỉ lệ thật để đặt mục tiêu sau có căn cứ'},{k:'b',t:'Mục tiêu cả team đi học thêm các khoá quảng cáo trong tháng đầu'},
             {k:'c',t:'Mục tiêu không cần đạt, vì tháng đầu chỉ là giai đoạn thử nghiệm'},{k:'d',t:'Mục tiêu học theo cách làm của đối thủ để bắt chước cho nhanh'}],
    answer:'a', why:{a:'Đúng. Học ở đây là học về chính khách hàng và phễu của mình.',
      b:'Khoá học có thể có ích nhưng không phải nghĩa của khái niệm.',
      c:'Mục tiêu học vẫn phải đạt: phải đo được số liệu, không phải không cần kết quả.',
      d:'Bắt chước không cho biết tỉ lệ thật của shop mình.'} },
  { type:'mcq', stem:'Một quán ăn mới mở muốn ước số khách tuần đầu mà không có dữ liệu. Nguồn tham khảo nào đáng dùng nhất?',
    options:[{k:'a',t:'Con số trung bình của các chuỗi nhà hàng lớn trên toàn quốc'},{k:'b',t:'Mong muốn của chủ quán để đủ hoàn vốn trong ba tháng đầu tiên'},
             {k:'c',t:'Lượt người qua lại trước cửa đếm vài buổi và số chỗ ngồi thực tế'},{k:'d',t:'Số lượt thích của bài đăng khai trương trên fanpage của quán'}],
    answer:'c', why:{a:'Chuỗi lớn có thương hiệu và vị trí khác hẳn quán mới.',
      b:'Mong muốn hoàn vốn là nhu cầu, không phải ước tính khách sẽ đến.',
      c:'Đúng. Lượng người qua lại cho phía cầu, số chỗ ngồi cho phía cung.',
      d:'Lượt thích ở xa hành vi đến ăn thật.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:gt06-08', skill:'measure', read:'7 phút', t:'Team 3 người có nên dùng OKR không?',
  situation:'Một thương hiệu gốm thủ công ở Bát Tràng có team marketing 3 người. Chủ thương hiệu đọc về OKR và muốn áp dụng. Bản nháp đầu tiên có 5 mục tiêu, mỗi mục tiêu 4 kết quả then chốt — tổng 20 con số cho một quý. Team nhìn vào và thấy choáng.',
  concept:{ name:'OKR gọn cho team nhỏ',
    body:'OKR gồm <b>Objective</b> — một câu mô tả điều muốn đạt, dễ nhớ và có ý nghĩa — và <b>Key Results</b> — 2 đến 3 con số chứng minh đã đạt. Với team nhỏ, một mục tiêu mỗi quý thường là đủ. Kết quả then chốt phải là kết quả, không phải việc làm: "ra mắt website" là việc, "40 đơn mỗi tháng từ website" là kết quả. Gắn nhãn từng KR: <b>cam kết</b> (phải đạt gần đủ, như giao hàng đúng hạn) hay <b>tham vọng</b> (đặt cao có chủ ý, đạt khoảng 70% đã là tốt nếu cả team hiểu trước quy ước). Team 2–3 người chưa cần OKR nếu một mục tiêu và vài con số trên một trang đã đủ; OKR đáng chi phí khi cần xếp ưu tiên giữa các việc tranh nhau sức người.' },
  example:'Rút 20 con số còn một bộ: Objective — "Khách ở Hà Nội mua gốm Bát Tràng online từ chúng ta thay vì phải về làng". KR1: đơn online từ Hà Nội tăng từ 50 lên 90 mỗi tháng. KR2: khách mua lại trong 90 ngày từ 12% lên 20%. KR3: điểm đánh giá đóng gói từ 4,2 lên 4,7 trên 5. Cuối quý đạt 77 đơn mỗi tháng: tăng 27 trên mức cần tăng 40, tức khoảng 68% tiến độ.',
  takeaway:'Team nhỏ: một mục tiêu, hai ba kết quả then chốt, và mỗi kết quả là con số chứ không phải việc làm.',
  apply:'Viết một Objective cho một shop bạn biết, kèm hai kết quả then chốt có con số. Đọc to trong 60 giây và tự kiểm: có câu nào là việc làm không?',
  mistakes:['Viết quá nhiều mục tiêu và kết quả then chốt cho team vài người.','Ghi việc làm như "ra mắt website" vào chỗ kết quả then chốt.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: team 3 người với 20 con số một quý, bạn đoán điều gì sẽ xảy ra?',
    options:[{k:'a',t:'Team sẽ làm việc chăm hơn vì có nhiều mục tiêu để phấn đấu cùng lúc'},{k:'b',t:'Các con số đều được theo dõi đủ nhờ bảng tính tự động'},
             {k:'c',t:'Sự chú ý bị chia nhỏ, không con số nào được đẩy đủ mạnh'},{k:'d',t:'Chủ thương hiệu sẽ có bức tranh đầy đủ nhất về hoạt động của team'}],
    answer:'c', why:{a:'Nhiều mục tiêu không tạo thêm giờ làm; nó chia nhỏ sức lực.',
      b:'Theo dõi được không có nghĩa là tác động được.',
      c:'Đúng. Ba người không thể cùng lúc đẩy 20 con số.',
      d:'Nhiều số liệu không bằng biết rõ điều gì quan trọng nhất.'} },
  { type:'mcq', stem:'Bạn được nhờ rút gọn bản nháp OKR. Bạn chọn cách nào?',
    options:[{k:'a',t:'Giữ 5 mục tiêu nhưng mỗi mục tiêu chỉ còn một kết quả then chốt'},{k:'b',t:'Chia 20 con số cho 3 người, mỗi người lo khoảng 6–7 con số riêng'},
             {k:'c',t:'Chuyển 20 con số sang theo dõi theo năm thay vì theo quý'},{k:'d',t:'Một mục tiêu gắn với vấn đề kinh doanh lớn nhất, kèm 2–3 kết quả'}],
    answer:'d', why:{a:'Năm hướng vẫn là năm hướng, chỉ ít con số hơn.',
      b:'Chia ra thì mỗi người vẫn quá tải và team không cùng hướng.',
      c:'Kéo dài thời gian không giải quyết việc quá nhiều ưu tiên.',
      d:'Đúng. Tập trung vào điều quan trọng nhất cho kinh doanh quý này.'} },
  { type:'calc', stem:'KR: tăng đơn online từ 50 lên 90 mỗi tháng. Cuối quý đạt 77 đơn mỗi tháng. Tiến độ đạt bao nhiêu phần trăm (làm tròn số nguyên)?',
    unit:'%', ans:68, tol:1, wrong:[[86,'SAI_MAU_SO'],[54,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Mức cần tăng = 90 − 50 = 40 đơn. Đã tăng = 77 − 50 = 27 đơn.','Tiến độ = 27 ÷ 40 = 0,675 ≈ <b>68%</b>.'] },
  { type:'mcq', stem:'Câu nào là một kết quả then chốt viết đúng?',
    options:[{k:'a',t:'Ra mắt website bán hàng mới trước ngày 15 tháng 8'},{k:'b',t:'Tỉ lệ khách mua lại trong 90 ngày tăng từ 15% lên 25%'},
             {k:'c',t:'Chạy 3 chiến dịch quảng cáo Facebook trong quý 3'},{k:'d',t:'Làm cho khách hàng yêu thích thương hiệu gốm hơn'}],
    answer:'b', why:{a:'Đây là việc làm; ra mắt xong vẫn có thể không có đơn nào.',
      b:'Đúng. Có điểm đầu, điểm đích, và đo kết quả chứ không đo công việc.',
      c:'Số chiến dịch là khối lượng việc, không phải kết quả.',
      d:'Không đo được; đây giống một Objective chưa gọt hơn là KR.'} },
  { type:'mcq', stem:'Cuối quý team đạt 68% ở hai KR: đơn online từ Hà Nội (nhãn tham vọng) và tỉ lệ đóng gói giao đúng hạn (nhãn cam kết). Bạn đánh giá thế nào?',
    options:[{k:'a',t:'KR tham vọng ổn nếu đã nói trước; KR cam kết hụt hơn 30% cần tìm nguyên nhân'},{k:'b',t:'Cả hai đều ổn vì đạt trên 60% là mốc tốt chung của mọi KR trong OKR'},
             {k:'c',t:'Cả hai đều thất bại vì chưa đạt đủ 100% con số đã đặt ra từ đầu quý'},{k:'d',t:'Chỉ cần xem KR tham vọng, còn KR cam kết không cần chấm điểm lại'}],
    answer:'a', why:{a:'Đúng. 68% có nghĩa khác nhau theo nhãn: tham vọng cố ý đặt cao, cam kết thì hụt là một vấn đề cần xử lý.',
      b:'Mốc 70% chỉ áp cho KR tham vọng; áp cho KR cam kết là tha thứ việc giao hàng trễ.',
      c:'Coi KR tham vọng là cam kết 100% khiến team chỉ dám đặt mục tiêu an toàn.',
      d:'KR cam kết là chỗ cần kiểm kỹ nhất vì khách đã được hứa; bỏ chấm là bỏ đúng chỗ rủi ro.'} },
  { type:'mcq', stem:'Một Objective tốt cho team nhỏ nên thế nào?',
    options:[{k:'a',t:'Một con số doanh thu cụ thể, ví dụ đạt 2 tỉ đồng trong quý này'},{k:'b',t:'Một danh sách đầy đủ các việc cần làm của cả team trong quý'},
             {k:'c',t:'Một câu dễ nhớ, có ý nghĩa, nói điều muốn đổi cho khách hoặc công ty'},{k:'d',t:'Một khẩu hiệu quảng cáo sẽ in lên bao bì và trang web của thương hiệu'}],
    answer:'c', why:{a:'Con số thuộc về KR; Objective là câu mô tả hướng đi.',
      b:'Danh sách việc là kế hoạch, không phải mục tiêu.',
      c:'Đúng. Objective nói điều muốn đạt; KR chứng minh đã đạt.',
      d:'Khẩu hiệu hướng ra khách; Objective là để team hiểu mình đang đi đâu.'} },
  { type:'mcq', stem:'Tiệm hoa 2 người chỉ có một mục tiêu cho mùa 20/10. Chủ tiệm hỏi có nên dùng OKR đầy đủ không. Bạn khuyên gì?',
    options:[{k:'a',t:'Có, chép nguyên bộ OKR của công ty công nghệ lớn rồi sửa tên cho hợp'},{k:'b',t:'Chưa cần quy trình riêng; một mục tiêu và 2 con số theo dõi hằng tuần là đủ'},
             {k:'c',t:'Có, đặt 4 mục tiêu cho 4 kênh bán hàng để không bỏ sót kênh nào'},{k:'d',t:'Có, và họp chấm điểm mỗi tuần để mọi người nắm toàn bộ các kết quả'}],
    answer:'b', why:{a:'Bộ mẫu của công ty lớn không hợp quy mô; chi phí vận hành vượt lợi ích với hai người.',
      b:'Đúng. Hai người nhìn nhau làm việc, chỉ cần một đích và vài con số; OKR đầy đủ chỉ đáng khi có nhiều ưu tiên tranh nhau.',
      c:'Bốn mục tiêu cho hai người là chia quá mỏng, đúng lỗi bản nháp 20 con số.',
      d:'Họp chấm điểm hằng tuần cho hai người là phí giờ; một dòng cập nhật là đủ.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:gt06-09', skill:'channel', read:'6 phút', t:'Chiến dịch một tháng — đặt mục tiêu sao cho biết ngày nào đang tụt?',
  situation:'Một thương hiệu balo học sinh ở TP.HCM chạy chiến dịch "Tựu trường" trong 4 tuần tháng 8, ngân sách 80 triệu đồng. Mục tiêu: 1.600 đơn. Tuần đầu bán 250 đơn. Trưởng nhóm bảo "vẫn ổn, còn ba tuần". Bạn thấy lo nhưng chưa biết lấy gì để nói.',
  concept:{ name:'Mục tiêu chiến dịch chia theo nhịp',
    body:'Mục tiêu một tháng cần được <b>chia ra theo tuần</b>, và không nhất thiết chia đều. Nhiều mùa có nhịp riêng: tựu trường dồn về hai tuần cuối trước ngày khai giảng; Tết dồn về giữa tháng Chạp. Đặt mục tiêu tuần theo nhịp dự kiến, kèm <b>chi phí mỗi đơn tối đa</b> để biết đang mua đơn quá đắt. So thực tế với mốc tuần là cách biết sớm chiến dịch đang tụt hay đang đúng nhịp.' },
  example:'Nhịp dự kiến: tuần 1 là 20%, tuần 2 là 25%, tuần 3 là 30%, tuần 4 là 25%. Mốc tuần 1 = 1.600 × 20% = 320 đơn. Thực tế 250 đơn, hụt khoảng 22% so với mốc — không phải "vẫn ổn". Chi phí mỗi đơn tối đa: 80 triệu ÷ 1.600 = 50.000 đồng. Tuần 1 đã tiêu 16 triệu cho 250 đơn, tức 64.000 đồng mỗi đơn: vừa ít đơn vừa đắt.',
  takeaway:'Chia mục tiêu tháng thành mốc tuần theo nhịp mùa, kèm trần chi phí mỗi đơn — lệch mốc là biết ngay.',
  points:["Mốc tuần cho phép sửa khi còn tiền và còn ngày. Hụt 70 đơn ở tuần 1 còn chỉnh được; cùng mức hụt đó dồn đến tuần 4 thì thường không còn chỗ xoay.","Chi phí mỗi đơn đo hiệu quả mua, còn số đơn đo quy mô. Đi cùng nhau, chúng cho biết bạn bán nhiều mà đắt hay ít mà rẻ, hai bệnh khác nhau.","Nhịp mùa lấy từ dữ liệu năm trước hoặc ngày khai giảng, nên ghi rõ giả định 20–25–30–25%. Khi giả định sai, bạn sửa các tỉ lệ này chứ không bỏ cả mục tiêu."],
  counter:"Mốc tuần theo nhịp dự kiến sẽ sai khi có sự kiện làm lệch nhịp. Giả sử trường dời khai giảng sớm một tuần, đơn dồn về tuần 3 thay vì tuần 4. Khi đó tuần 1 hụt so với mốc 320 đơn chưa chắc là xấu. Dấu hiệu là các chỉ số sớm như lượt thêm vào giỏ hàng hụt đều trong khi chi phí mỗi đơn vẫn trong trần.",
  deeper:"Người làm nghề đọc mốc tuần như một tín hiệu chứ không phải bản án. Đánh đổi là mốc quá sát làm đội hoảng vì dao động nhỏ, mốc quá rộng thì không báo động kịp. Tín hiệu nên theo dõi ngoài số đơn là chi phí mỗi đơn theo từng ngày, vì nó thường tăng trước khi đơn tụt. Khái niệm kề cận là chỉ số dẫn đầu: lượt thêm vào giỏ hàng cho biết sớm hơn số đơn. Phép kiểm tra trong tuần: chia 80 triệu đồng theo bốn tuần với cùng tỉ lệ nhịp mùa, rồi so mức tiêu thực tế với mức tiêu dự kiến của từng tuần.",
  apply:'Chọn một dịp bán hàng bạn quen như Tết hay 8/3. Nói trong 60 giây: tuần nào đơn sẽ dồn nhiều nhất, và bạn chia mục tiêu thế nào.',
  mistakes:['Chia đều mục tiêu cho mọi tuần dù mùa bán có nhịp rõ ràng.','Chỉ nhìn số đơn mà quên chi phí mỗi đơn, đạt số nhưng lỗ.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: chiến dịch tựu trường 4 tuần, bạn đoán đơn thường dồn vào lúc nào?',
    options:[{k:'a',t:'Đều nhau cả bốn tuần vì phụ huynh mua rải rác'},{k:'b',t:'Dồn hết vào tuần đầu vì phụ huynh mua sớm cho chắc'},
             {k:'c',t:'Dồn nhiều ở các tuần sát ngày khai giảng'},{k:'d',t:'Dồn vào sau khai giảng khi học sinh thấy bạn có đồ mới'}],
    answer:'c', why:{a:'Mùa tựu trường có nhịp rõ; chia đều sẽ đặt sai mốc.',
      b:'Có người mua sớm nhưng phần đông mua khi ngày khai giảng đã gần.',
      c:'Đúng. Nhu cầu tăng khi hạn chót đến gần.',
      d:'Có một ít đơn sau khai giảng, nhưng đỉnh là trước đó.'} },
  { type:'mcq', stem:'Tuần 1 bán 250 đơn, mốc tuần 1 là 320 đơn, chi phí mỗi đơn 64.000 đồng so với trần 50.000 đồng. Bạn đề xuất gì?',
    options:[{k:'a',t:'Chưa cần làm gì vì tuần đầu vốn chậm, đợi các tuần cao điểm sau'},{k:'b',t:'Tăng gấp đôi ngân sách tuần 2 để bù cho phần đơn hụt của tuần 1'},
             {k:'c',t:'Báo hụt mốc, soi nhóm quảng cáo đắt nhất và dời tiền sang nhóm rẻ hơn'},{k:'d',t:'Giảm giá balo 25% ngay lập tức để kéo đủ đơn trong tuần thứ hai'}],
    answer:'c', why:{a:'Mốc tuần đã tính cả chuyện tuần đầu chậm; vẫn hụt là có vấn đề.',
      b:'Đơn đang đắt; đổ thêm tiền vào cùng cách làm sẽ càng lỗ.',
      c:'Đúng. Vấn đề là chi phí mỗi đơn; sửa hiệu quả trước khi tăng tiền.',
      d:'Giảm giá sâu làm mất lãi trong khi chưa rõ nguyên nhân hụt.'} },
  { type:'calc', stem:'Ngân sách 80 triệu đồng, mục tiêu 1.600 đơn. Tuần 1 tiêu 16 triệu đồng được 250 đơn. Chi phí mỗi đơn tuần 1 cao hơn trần bao nhiêu đồng?',
    unit:'đồng', ans:14000, tol:1, wrong:[[64000,'SAI_TINH_TOAN'],[50000,'SAI_MAU_SO']], errors:['SAI_TINH_TOAN'],
    steps:['Trần = 80.000.000 ÷ 1.600 = 50.000 đồng/đơn. Tuần 1 = 16.000.000 ÷ 250 = 64.000 đồng/đơn.','Cao hơn: 64.000 − 50.000 = <b>14.000 đồng</b>.'] },
  { type:'mcq', stem:'Vì sao cần trần chi phí mỗi đơn bên cạnh mục tiêu số đơn?',
    options:[{k:'a',t:'Vì nền tảng quảng cáo yêu cầu khai báo trần chi phí trước khi chạy'},{k:'b',t:'Vì đạt đủ đơn bằng cách đổ tiền không giới hạn có thể làm lỗ'},
             {k:'c',t:'Vì chi phí mỗi đơn thường tự giảm khi chiến dịch chạy lâu'},{k:'d',t:'Vì kế toán chỉ hiểu chi phí, không hiểu số đơn trong báo cáo'}],
    answer:'b', why:{a:'Nền tảng không bắt buộc; đây là giới hạn doanh nghiệp tự đặt.',
      b:'Đúng. Số đơn không có giới hạn chi phí thì mục tiêu đạt được bằng cách đốt tiền.',
      c:'Chi phí có thể tăng khi đối thủ cùng chạy mùa cao điểm.',
      d:'Lý do không phải ai hiểu gì, mà là để giữ lãi.'} },
  { type:'mcq', stem:'Mục tiêu tháng 1.600 đơn, nhịp tuần 20–25–30–25%. Mốc tuần 3 là bao nhiêu đơn?',
    options:[{k:'a',t:'400 đơn, vì chia đều 1.600 đơn cho bốn tuần như nhau'},{k:'b',t:'1.200 đơn, vì đó là tổng cộng dồn của ba tuần đầu tiên'},
             {k:'c',t:'300 đơn, vì tuần ba thường chậm lại sau hai tuần đầu'},{k:'d',t:'480 đơn, tức 30% của 1.600'}],
    answer:'d', why:{a:'Chia đều bỏ qua nhịp mùa đã đặt.',
      b:'Cộng dồn ba tuần là 75% × 1.600 = 1.200, nhưng câu hỏi là mốc riêng tuần 3.',
      c:'Tuần 3 là tuần cao nhất theo nhịp đã đặt, không phải chậm lại.',
      d:'Đúng. 1.600 × 30% = 480 đơn.'} },
  { type:'mcq', stem:'Một cửa hàng hoa chạy chiến dịch 8/3 kéo dài 10 ngày. Cách chia mục tiêu nào hợp lý nhất?',
    options:[{k:'a',t:'Chia đều cho 10 ngày để dễ theo dõi và dễ báo cáo mỗi tối'},{k:'b',t:'Mốc nhỏ ở các ngày đầu, dồn phần lớn vào 2–3 ngày sát 8/3'},
             {k:'c',t:'Dồn phần lớn vào ngày đầu vì khách thường đặt hoa rất sớm'},{k:'d',t:'Không chia mốc ngày, chỉ tổng kết sau khi kết thúc chiến dịch'}],
    answer:'b', why:{a:'Chia đều sẽ làm những ngày đầu trông như đang hụt nặng.',
      b:'Đúng. Hoa là quà sát ngày; nhịp dồn về cuối.',
      c:'Một phần khách đặt sớm, nhưng đỉnh vẫn là sát ngày.',
      d:'Không có mốc thì mất khả năng sửa trong 10 ngày ngắn ngủi.'} },
  { type:'mcq', stem:'Cuối tuần 2, số đơn cộng dồn đúng mốc nhưng chi phí mỗi đơn vẫn cao hơn trần. Kết luận nào đúng?',
    options:[{k:'a',t:'Chiến dịch đạt, vì số đơn mới là mục tiêu chính của chiến dịch'},{k:'b',t:'Chi phí cao là bình thường ở mùa cao điểm, không cần xem xét gì'},
             {k:'c',t:'Đúng nhịp về số đơn nhưng vượt giới hạn chi phí, cần sửa hiệu quả'},{k:'d',t:'Nên dừng chiến dịch ngay vì đã không còn khả năng có lãi nữa'}],
    answer:'c', why:{a:'Trần chi phí là một phần của mục tiêu, không phải phụ.',
      b:'Có thể đắt hơn mùa thường, nhưng trần đã đặt cho chính mùa này.',
      c:'Đúng. Hai mặt của mục tiêu phải xem cùng nhau.',
      d:'Vượt trần chưa chắc đã lỗ; cần sửa trước khi dừng.'} }
  ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:gt06-10', skill:'comm', read:'6 phút', t:'Hụt mục tiêu quý — báo cáo sao cho trung thực mà vẫn có ích?',
  situation:'Mục tiêu quý của một thương hiệu cà phê rang xay online ở Đắk Lắk là 900 khách mới. Kết quả: 630 khách. Cuộc họp tổng kết là sáng thứ Hai. Đồng nghiệp gợi ý đổi sang báo "lượt tiếp cận tăng 150%" cho đẹp, hoặc gộp khách cũ vào để con số gần 900 hơn.',
  concept:{ name:'Báo cáo trung thực khi không đạt',
    body:'Báo cáo tốt khi hụt có ba phần: <b>con số thật so với mục tiêu</b>, nói ngay ở câu đầu; <b>nguyên nhân</b> tách được theo phễu — hụt ở tầng nào, vì sao; và <b>bước tiếp theo</b> cụ thể. Đổi thước đo hoặc gộp số để trông đẹp có thể qua được một cuộc họp, nhưng làm hỏng thứ quý nhất của người làm marketing: lời nói có người tin. Sếp cần biết sớm để điều tiền, không cần một báo cáo dễ nghe.' },
  example:'Câu mở: "Quý này đạt 630/900 khách mới, bằng 70%." Tách phễu: lượt vào trang đạt đúng kế hoạch 30.000 lượt, nhưng tỉ lệ mua chỉ 2,1% so với 3% dự kiến — hụt nằm ở trang sản phẩm, không ở quảng cáo. Nguyên nhân khả nghi: phí ship lộ ra ở bước cuối. Bước tiếp: thử miễn phí ship cho đơn từ 300.000 đồng trong 4 tuần, mục tiêu đưa tỉ lệ mua lên 2,7%.',
  takeaway:'Hụt thì nói số thật ở câu đầu, chỉ đúng tầng hụt, và kèm một bước tiếp có con số.',
  points:["Con số thật ở câu đầu giữ quyền kiểm soát câu chuyện. Người nghe không phải đoán bạn giấu gì, nên phần phân tích sau đó nghe như giải thích chứ không như bào chữa.","Tách theo phễu biến thất bại chung thành một vị trí cụ thể. Lượt vào trang đạt kế hoạch thì quảng cáo đã làm đúng việc, phần cần sửa nằm ở trang sản phẩm.","Bước tiếp có con số biến báo cáo thành quyết định. Thử miễn phí ship trong 4 tuần để đưa tỉ lệ mua lên 2,7% cho sếp thứ để đồng ý hoặc từ chối."],
  counter:"Cách báo cáo này có thể gây hiểu lầm khi nguyên nhân chưa rõ mà bạn viết như đã chắc. Giả sử phí ship chỉ là một trong vài nghi ngờ, trang sản phẩm chưa được thử. Nếu ghi như kết luận, sếp sẽ duyệt một thử nghiệm sai chỗ. Dấu hiệu là bạn chưa có dữ liệu loại trừ nguyên nhân khác. Khi đó hãy ghi là giả thuyết và nêu cách kiểm tra rẻ nhất.",
  deeper:"Người làm nghề nghĩ về uy tín như một tài khoản: mỗi lần báo số thật là gửi vào, mỗi lần đổi thước đo là rút ra. Đánh đổi là cuộc họp hôm đó khó chịu hơn, nhưng lần sau sếp tin cả những con số tốt của bạn. Tín hiệu nên theo dõi là các chỉ số phụ như lượt tiếp cận có bị đem ra thay cho mục tiêu chính hay không. Khái niệm kề cận là phân tích phễu, công cụ giúp chỉ đúng tầng hụt. Phép kiểm tra trong tuần: viết câu đầu của báo cáo quý gần nhất và xem nó có chứa con số cam kết ban đầu kèm kết quả thật không.",
  apply:'Nhớ lại một lần bạn hoặc team không đạt mục tiêu. Nói lại trong 60 giây theo ba phần: số thật, tầng hụt, bước tiếp theo.',
  mistakes:['Đổi sang chỉ số đẹp hơn để né con số chính đã cam kết.','Chỉ xin lỗi mà không tách được hụt ở tầng nào của phễu.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: hụt 30% mục tiêu, điều gì nên nằm ở câu đầu tiên của báo cáo?',
    options:[{k:'a',t:'Con số thật so với mục tiêu: 630 trên 900, bằng 70%'},{k:'b',t:'Lượt tiếp cận tăng 150%, để mở đầu bằng một tin tích cực'},
             {k:'c',t:'Danh sách các khó khăn khách quan của thị trường quý này'},{k:'d',t:'Lời xin lỗi của team vì đã không làm tròn trách nhiệm'}],
    answer:'a', why:{a:'Đúng. Người nghe cần biết ngay kết quả chính; mọi thứ khác đi sau.',
      b:'Mở bằng số khác để né là cách làm người nghe mất lòng tin khi phát hiện.',
      c:'Nói khó khăn trước nghe như biện minh trước khi nêu kết quả.',
      d:'Xin lỗi không cho sếp thông tin để quyết định.'} },
  { type:'mcq', stem:'Đồng nghiệp muốn gộp khách cũ vào số khách mới cho gần 900. Bạn chọn cách làm nào?',
    options:[{k:'a',t:'Đồng ý gộp, vì khách cũ mua lại cũng là doanh thu cho công ty mà'},{k:'b',t:'Gộp nhưng ghi chú nhỏ ở cuối báo cáo để lỡ ai hỏi thì vẫn có nói'},
             {k:'c',t:'Báo khách cũ riêng, số khách mới giữ nguyên 630 như đã cam kết'},{k:'d',t:'Bỏ con số khách mới khỏi báo cáo, chỉ nói về tổng doanh thu'}],
    answer:'c', why:{a:'Mục tiêu đã cam kết là khách mới; gộp là đổi định nghĩa sau khi thua.',
      b:'Ghi chú nhỏ vẫn là che giấu; người đọc lướt sẽ hiểu sai.',
      c:'Đúng. Khách cũ mua lại là tin tốt riêng, báo riêng; không trộn vào để che hụt.',
      d:'Bỏ con số đã cam kết khiến người nghe càng nghi.'} },
  { type:'calc', stem:'Quý có 30.000 lượt vào trang. Tỉ lệ mua thực tế 2,1%, dự kiến 3%. Hụt bao nhiêu khách so với dự kiến chỉ vì tỉ lệ mua?',
    unit:'khách', ans:270, tol:1, wrong:[[900,'QUEN_TI_LE_CHUYEN_DOI'],[630,'NHAM_SO_TUYET_DOI']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Dự kiến: 30.000 × 3% = 900 khách. Thực tế: 30.000 × 2,1% = 630 khách.','Hụt: 900 − 630 = <b>270 khách</b>.'] },
  { type:'mcq', stem:'Lượt vào trang đạt đúng kế hoạch nhưng tỉ lệ mua chỉ 2,1% so với 3%. Hụt nằm ở đâu?',
    options:[{k:'a',t:'Ở quảng cáo, vì quảng cáo không kéo đủ người vào trang bán'},{k:'b',t:'Ở sản phẩm cà phê, vì chất lượng hạt rang không đủ tốt'},
             {k:'c',t:'Ở mục tiêu, vì 900 khách mới là con số đặt quá cao'},{k:'d',t:'Ở bước từ trang sản phẩm đến lúc mua'}],
    answer:'d', why:{a:'Lượt vào trang đạt đủ kế hoạch; quảng cáo đã làm đủ phần.',
      b:'Khách chưa mua thì chưa nếm; chất lượng hạt không giải thích được tỉ lệ mua lần đầu.',
      c:'Có thể, nhưng dữ liệu chỉ ra một tầng cụ thể đang yếu.',
      d:'Đúng. Người đã vào nhưng không mua — tầng trang và thanh toán.'} },
  { type:'mcq', stem:'Sếp hỏi: "Vậy quý sau làm gì?" Câu trả lời nào có ích nhất?',
    options:[{k:'a',t:'Team sẽ cố gắng nhiều hơn nữa và rút kinh nghiệm sâu sắc cho quý sau'},{k:'b',t:'Thử miễn phí ship từ 300.000 đồng trong 4 tuần, mục tiêu tỉ lệ mua 2,7%'},
             {k:'c',t:'Tăng ngân sách quảng cáo thêm 50% để kéo thêm thật nhiều người vào trang'},{k:'d',t:'Đổi mục tiêu quý sau sang lượt tiếp cận vì đó là chỉ số team đang làm tốt'}],
    answer:'b', why:{a:'"Cố gắng hơn" không nói làm gì, không đo được.',
      b:'Đúng. Hành động cụ thể, nhắm đúng tầng hụt, có thời hạn và con số.',
      c:'Kéo thêm người vào một trang đang rò rỉ là đổ tiền vào chỗ yếu.',
      d:'Đổi sang chỉ số mình giỏi là né vấn đề chứ không giải quyết.'} },
  { type:'mcq', stem:'Vì sao đổi sang báo "lượt tiếp cận tăng 150%" lại có hại về lâu dài?',
    options:[{k:'a',t:'Vì lượt tiếp cận là con số không thể nào đo được chính xác'},{k:'b',t:'Vì con số 150% quá lớn nên sếp sẽ nghi ngờ ngay từ đầu'},
             {k:'c',t:'Vì báo cáo sau không ai tin nữa khi phát hiện bị né'},{k:'d',t:'Vì tiếp cận tăng thì số khách mới thường giảm theo'}],
    answer:'c', why:{a:'Tiếp cận đo được trên nền tảng; vấn đề không phải độ chính xác.',
      b:'Sếp có thể không nghi ngay; cái hại đến khi phát hiện.',
      c:'Đúng. Mất lòng tin thì mọi con số sau đó đều bị đặt dấu hỏi.',
      d:'Không có quy luật như vậy; hai con số có thể cùng tăng.'} },
  { type:'mcq', stem:'Một bạn làm marketing ở chuỗi nha khoa đạt 85% mục tiêu lượt đặt hẹn. Báo cáo nào trung thực và có ích nhất?',
    options:[{k:'a',t:'Đạt 85% lượt đặt hẹn; hụt ở chi nhánh mới, sẽ thử thêm khung giờ tối'},{k:'b',t:'Lượt đặt hẹn gần đạt, tình hình chung khả quan, team tiếp tục cố gắng'},
             {k:'c',t:'Đạt 85% nhưng do thị trường chung khó khăn nên kết quả đã là rất tốt'},{k:'d',t:'Lượt xem trang web tăng mạnh, cho thấy thương hiệu đang lan toả tốt'}],
    answer:'a', why:{a:'Đúng. Số thật, chỗ hụt cụ thể, và một bước tiếp theo rõ ràng.',
      b:'"Gần đạt" và "khả quan" làm mờ con số, không có bước tiếp.',
      c:'Đổ cho thị trường mà không có bằng chứng là biện minh.',
      d:'Né con số chính bằng một chỉ số khác.'} }
  ] }

] });
